const _astro_dataLayerContent = [["Map",1,2,9,10],"meta::meta",["Map",3,4,5,6,7,8],"astro-version","5.18.1","content-config-digest","872729288030c224","astro-config-digest","{\"root\":{},\"srcDir\":{},\"publicDir\":{},\"outDir\":{},\"cacheDir\":{},\"site\":\"https://blog.palczew.ski\",\"compressHTML\":true,\"base\":\"/\",\"trailingSlash\":\"ignore\",\"output\":\"static\",\"scopedStyleStrategy\":\"attribute\",\"build\":{\"format\":\"directory\",\"client\":{},\"server\":{},\"assets\":\"_astro\",\"serverEntry\":\"entry.mjs\",\"redirects\":true,\"inlineStylesheets\":\"auto\",\"concurrency\":1},\"server\":{\"open\":false,\"host\":false,\"port\":4321,\"streaming\":true,\"allowedHosts\":[]},\"redirects\":{},\"prefetch\":{\"defaultStrategy\":\"hover\"},\"image\":{\"endpoint\":{\"route\":\"/_image\"},\"service\":{\"entrypoint\":\"astro/assets/services/sharp\",\"config\":{}},\"domains\":[],\"remotePatterns\":[],\"responsiveStyles\":false},\"devToolbar\":{\"enabled\":true},\"markdown\":{\"syntaxHighlight\":{\"type\":\"shiki\",\"excludeLangs\":[\"math\"]},\"shikiConfig\":{\"langs\":[],\"langAlias\":{},\"theme\":\"css-variables\",\"themes\":{},\"wrap\":false,\"transformers\":[]},\"remarkPlugins\":[null,null,null],\"rehypePlugins\":[null,null],\"remarkRehype\":{},\"gfm\":true,\"smartypants\":true},\"i18n\":{\"defaultLocale\":\"en\",\"locales\":[\"pl\",\"en\"],\"routing\":{\"prefixDefaultLocale\":true,\"redirectToDefaultLocale\":false,\"fallbackType\":\"redirect\"}},\"security\":{\"checkOrigin\":true,\"allowedDomains\":[],\"actionBodySizeLimit\":1048576},\"env\":{\"schema\":{},\"validateSecrets\":false},\"experimental\":{\"clientPrerender\":false,\"contentIntellisense\":false,\"headingIdCompat\":false,\"preserveScriptOrder\":false,\"fonts\":[{\"name\":\"Space Grotesk\",\"cssVariable\":\"--font-space-grotesk\",\"provider\":{\"name\":\"google\"},\"weights\":[300,400,500,600,700],\"styles\":[\"normal\"],\"subsets\":[\"latin\",\"latin-ext\"]},{\"name\":\"Newsreader\",\"cssVariable\":\"--font-newsreader\",\"provider\":{\"name\":\"google\"},\"weights\":[300,400,500,600,700],\"styles\":[\"normal\",\"italic\"],\"subsets\":[\"latin\",\"latin-ext\"]},{\"name\":\"JetBrains Mono\",\"cssVariable\":\"--font-jetbrains-mono\",\"provider\":{\"name\":\"google\"},\"weights\":[400,500],\"styles\":[\"normal\"],\"subsets\":[\"latin\",\"latin-ext\"]},{\"name\":\"Brygada 1918\",\"cssVariable\":\"--font-brygada-1918\",\"provider\":{\"name\":\"google\"},\"weights\":[400,500,600],\"styles\":[\"normal\",\"italic\"],\"subsets\":[\"latin\",\"latin-ext\"]}],\"liveContentCollections\":false,\"csp\":false,\"staticImportMetaEnv\":false,\"chromeDevtoolsWorkspace\":false,\"failOnPrerenderConflict\":false,\"svgo\":false},\"legacy\":{\"collections\":false}}","thoughts",["Map",11,12,40,41,77,78,117,118,143,144,169,170,197,198,268,269,303,304,327,328,352,353,376,377,403,404,415,416,438,439,447,448,470,471,492,493,523,524,544,545,566,567,598,599,641,642],"en/2025/11/articles-used-in-creating-this-blog",{id:11,data:13,body:20,filePath:21,digest:22,rendered:23},{title:14,date:15,tags:16,translationKey:18,draft:19},"Articles used in creating this blog",["Date","2025-11-13T00:00:00.000Z"],[17],"Web-development","2025-11-13-articles-used-in-creating-this-blog",true,"Just to point out sources that saved me a bit of ~~googling~~ tokens:\n- https://www.andrewhoog.com/posts/how-to-annotate-blog-posts-with-footnotes-in-astro/ [^1]\n\n\n[^1]: It works!","src/content/thoughts/en/2025/11/articles-used-in-creating-this-blog.md","65480184887820e6",{html:24,metadata:25},"<p>Just to point out sources that saved me a bit of <del>googling</del> tokens:</p>\n<ul>\n<li><a href=\"https://www.andrewhoog.com/posts/how-to-annotate-blog-posts-with-footnotes-in-astro/\">https://www.andrewhoog.com/posts/how-to-annotate-blog-posts-with-footnotes-in-astro/</a> <sup><a href=\"#user-content-fn-1\" id=\"user-content-fnref-1\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">1</a></sup></li>\n</ul>\n<section data-footnotes=\"\" class=\"footnotes\"><h2 class=\"\" id=\"footnote-label\">Footnotes</h2>\n<ol>\n<li id=\"user-content-fn-1\">\n<p>It works! <a href=\"#user-content-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",{headings:26,localImagePaths:31,remoteImagePaths:32,frontmatter:33,imagePaths:39},[27],{depth:28,slug:29,text:30},2,"footnote-label","Footnotes",[],[],{title:14,description:34,date:35,tags:36,draft:19,lang:37,translationKey:18,previewHtml:38},"A new post about web-development",["Date","2025-11-13T00:00:00.000Z"],[17],"en","<p>Just to point out sources that saved me a bit of <del>googling</del> tokens:</p>\n<ul>\n<li><a href=\"https://www.andrewhoog.com/posts/how-to-annotate-blog-posts-with-footnotes-in-astro/\">https://www.andrewhoog.com/posts/how-to-annotate-blog-posts-with-footnotes-in-astro/</a> <sup><a href=\"#user-content-en-2025-11-articles-used-in-creating-this-blog-fn-1\" id=\"user-content-en-2025-11-articles-used-in-creating-this-blog-fnref-1\" data-footnote-ref aria-describedby=\"footnote-label\">1</a></sup></li>\n</ul>\n<section data-footnotes class=\"footnotes\"><h2 class=\"sr-only\" id=\"footnote-label\">Footnotes</h2>\n<ol>\n<li id=\"user-content-en-2025-11-articles-used-in-creating-this-blog-fn-1\">\n<p>It works! <a href=\"#user-content-en-2025-11-articles-used-in-creating-this-blog-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",[],"en/2023/08/github-page-another-repo",{id:40,data:42,body:52,filePath:53,digest:54,rendered:55},{title:43,date:44,tags:45,draft:51},"Implication of deploying github page to another repo",["Date","2023-08-17T13:39:43.000Z"],[46,47,48,49,50],"Astro","Github","CD","Github-actions","Devops",false,"_Be aware that it is a n old post. Just reference or an inspiration if someone is lost._\n\n\nYears ago I had a thought to seperate repo with hugo theme and the one with rendered page due to possible use of [utterances](https://utteranc.es/)[^1]. There are my experiences with both approaches:\n\n## deploying page to the same repo\n\n- Astro docs provides a [good starting point](https://docs.astro.build/en/guides/deploy/github/)\n\n## deploying site elsewhere\n\n- There is a a [convinient github-action](https://cpina.github.io/push-to-another-repository-docs/index.html)\n- Can you reuse `withastro/action@v0` to build it? You might, but it is designed for scenario above, this action creates an [artifact](https://docs.github.com/en/actions/using-workflows/storing-workflow-data-as-artifacts) that is consumed by `actions/deploy-pages@v1` action.\n  - tl;dr: there are better ways\n\n### Example of deploying astro blog to github pages\n\n[There is my example](https://github.com/jpalczewski/entuzjazm/blob/6bd91f3a1d60714ab80836c2125b2a654d3a1b63/.github/workflows/deploy.yml) of working github action.\n\nThings worth to note:\n\n- By using actions to install node and pnpm there is huge time savings due to caching.\n- There should be a `.nojekyll` file in blog root - otherwise css is messed up[^2]\n\n[^1]: Is it a good idea? One of tutorials on integrating utterances with astro doesn't have it either. I hope not to see it as a opinion whether this is good option, but someday I will give it a try.\n[^2]: [Source](https://stackoverflow.com/questions/74489844/astro-js-deployment-media-files-not-rendering)","src/content/thoughts/en/2023/08/github-page-another-repo.md","4b5447735bc2fc50",{html:56,metadata:57},"<p><em>Be aware that it is a n old post. Just reference or an inspiration if someone is lost.</em></p>\n<p>Years ago I had a thought to seperate repo with hugo theme and the one with rendered page due to possible use of <a href=\"https://utteranc.es/\">utterances</a><sup><a href=\"#user-content-fn-1\" id=\"user-content-fnref-1\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">1</a></sup>. There are my experiences with both approaches:</p>\n<h2 id=\"deploying-page-to-the-same-repo\">deploying page to the same repo</h2>\n<ul>\n<li>Astro docs provides a <a href=\"https://docs.astro.build/en/guides/deploy/github/\">good starting point</a></li>\n</ul>\n<h2 id=\"deploying-site-elsewhere\">deploying site elsewhere</h2>\n<ul>\n<li>There is a a <a href=\"https://cpina.github.io/push-to-another-repository-docs/index.html\">convinient github-action</a></li>\n<li>Can you reuse <code>withastro/action@v0</code> to build it? You might, but it is designed for scenario above, this action creates an <a href=\"https://docs.github.com/en/actions/using-workflows/storing-workflow-data-as-artifacts\">artifact</a> that is consumed by <code>actions/deploy-pages@v1</code> action.\n<ul>\n<li>tl;dr: there are better ways</li>\n</ul>\n</li>\n</ul>\n<h3 id=\"example-of-deploying-astro-blog-to-github-pages\">Example of deploying astro blog to github pages</h3>\n<p><a href=\"https://github.com/jpalczewski/entuzjazm/blob/6bd91f3a1d60714ab80836c2125b2a654d3a1b63/.github/workflows/deploy.yml\">There is my example</a> of working github action.</p>\n<p>Things worth to note:</p>\n<ul>\n<li>By using actions to install node and pnpm there is huge time savings due to caching.</li>\n<li>There should be a <code>.nojekyll</code> file in blog root - otherwise css is messed up<sup><a href=\"#user-content-fn-2\" id=\"user-content-fnref-2\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">2</a></sup></li>\n</ul>\n<section data-footnotes=\"\" class=\"footnotes\"><h2 class=\"\" id=\"footnote-label\">Footnotes</h2>\n<ol>\n<li id=\"user-content-fn-1\">\n<p>Is it a good idea? One of tutorials on integrating utterances with astro doesn’t have it either. I hope not to see it as a opinion whether this is good option, but someday I will give it a try. <a href=\"#user-content-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-fn-2\">\n<p><a href=\"https://stackoverflow.com/questions/74489844/astro-js-deployment-media-files-not-rendering\">Source</a> <a href=\"#user-content-fnref-2\" data-footnote-backref=\"\" aria-label=\"Back to reference 2\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",{headings:58,localImagePaths:70,remoteImagePaths:71,frontmatter:72,imagePaths:76},[59,62,65,69],{depth:28,slug:60,text:61},"deploying-page-to-the-same-repo","deploying page to the same repo",{depth:28,slug:63,text:64},"deploying-site-elsewhere","deploying site elsewhere",{depth:66,slug:67,text:68},3,"example-of-deploying-astro-blog-to-github-pages","Example of deploying astro blog to github pages",{depth:28,slug:29,text:30},[],[],{title:43,language:37,date:73,tags:74,previewHtml:75},["Date","2023-08-17T13:39:43.000Z"],[46,47,48,49,50],"<p><em>Be aware that it is a n old post. Just reference or an inspiration if someone is lost.</em></p>\n<p>Years ago I had a thought to seperate repo with hugo theme and the one with rendered page due to possible use of <a href=\"https://utteranc.es/\">utterances</a><sup><a href=\"#user-content-en-2023-08-github-page-another-repo-fn-1\" id=\"user-content-en-2023-08-github-page-another-repo-fnref-1\" data-footnote-ref aria-describedby=\"footnote-label\">1</a></sup>. There are my experiences with both approaches:</p>\n<h2>deploying page to the same repo</h2>\n<ul>\n<li>Astro docs provides a <a href=\"https://docs.astro.build/en/guides/deploy/github/\">good starting point</a></li>\n</ul>\n<h2>deploying site elsewhere</h2>\n<ul>\n<li>There is a a <a href=\"https://cpina.github.io/push-to-another-repository-docs/index.html\">convinient github-action</a></li>\n<li>Can you reuse <code>withastro/action@v0</code> to build it? You might, but it is designed for scenario above, this action creates an <a href=\"https://docs.github.com/en/actions/using-workflows/storing-workflow-data-as-artifacts\">artifact</a> that is consumed by <code>actions/deploy-pages@v1</code> action.\n<ul>\n<li>tl;dr: there are better ways</li>\n</ul>\n</li>\n</ul>\n<h3>Example of deploying astro blog to github pages</h3>\n<p><a href=\"https://github.com/jpalczewski/entuzjazm/blob/6bd91f3a1d60714ab80836c2125b2a654d3a1b63/.github/workflows/deploy.yml\">There is my example</a> of working github action.</p>\n<p>Things worth to note:</p>\n<ul>\n<li>By using actions to install node and pnpm there is huge time savings due to caching.</li>\n<li>There should be a <code>.nojekyll</code> file in blog root - otherwise css is messed up<sup><a href=\"#user-content-en-2023-08-github-page-another-repo-fn-2\" id=\"user-content-en-2023-08-github-page-another-repo-fnref-2\" data-footnote-ref aria-describedby=\"footnote-label\">2</a></sup></li>\n</ul>\n<section data-footnotes class=\"footnotes\"><h2 class=\"sr-only\" id=\"footnote-label\">Footnotes</h2>\n<ol>\n<li id=\"user-content-en-2023-08-github-page-another-repo-fn-1\">\n<p>Is it a good idea? One of tutorials on integrating utterances with astro doesn’t have it either. I hope not to see it as a opinion whether this is good option, but someday I will give it a try. <a href=\"#user-content-en-2023-08-github-page-another-repo-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-en-2023-08-github-page-another-repo-fn-2\">\n<p><a href=\"https://stackoverflow.com/questions/74489844/astro-js-deployment-media-files-not-rendering\">Source</a> <a href=\"#user-content-en-2023-08-github-page-another-repo-fnref-2\" data-footnote-backref=\"\" aria-label=\"Back to reference 2\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",[],"en/2023/08/zotero-experience",{id:77,data:79,body:89,filePath:90,digest:91,rendered:92},{title:80,date:81,tags:82,draft:51},"How to improve Zotero experience?",["Date","2023-08-29T02:13:17.000Z"],[83,84,85,86,87,88],"Zotero","Latex","Notion","Obsidian","Sajna","Note-taking","_It's an old note, just for archival purposes. There might be newer alternatives. Also, old blog template used another method of referencing urls, don't have it yet here, so leaving it as-is: [link](\"https://beepb00p.xyz/annotating.html\")_\n\nI have a need to share how much I love [Zotero](https://www.zotero.org/). It was a tool that was a significant part of my academic journey and I had fallen in love while I was writing my B.Sc. thesis[^1], and all coexisting add-ons were indirectly responsible for about 50 references mentioned. I've recently also incorporated Zotero into my workflow alongside another side-project on Notion.\n\nOther remarkable features that Zotero offers:\n\n- Awesome notes on existing PDFs. A bit better than [hypothes.is](https://web.hypothes.is/)[^3] what was my main driver in B.Sc. era for taking notes from PDFs.[^4]\n- Collection mechanism - it's a bit specific approach for zotero and needs time to be used to.\n- Group collections that you can share your findings in teams.[^5]\n\nWhat add-ons were helpful?\n\n## Firefox extension\n\n[Zotero Connector for Firefox](https://www.zotero.org/download/connectors) simplifies the process of adding new database entries. A single click can trigger metadata extraction, and in some cases, even full-text PDF retrieval.[^2]\n\n## Better Bibtex\n\n[Better Bibtex](https://retorque.re/zotero-better-bibtex/) allows exporting yours database in format compatible with Latex.\n\n### Only Latex?\n\nIf you need a place to take notes and mention/link your entries, [Obsidian](https://obsidian.md/) might be a good place to start. There is a great tutorial that was a great inspiration, available [here](vhttps://medium.com/@alexandraphelan/an-academic-workflow-zotero-obsidian-56bf918d51ab).\n\nThere is a newer approach, however, that might work a bit better - [Obsidian Zotero Plugin](https://github.com/PKM-er/obsidian-zotero). Haven't tested yet.\n\n## But what if I want to share my zotero-based entries with friends?\n\nSometime tool just doesn't suit well, and forcing others to use obsidian might be imposing useless cognitive overload, so then Notion comes into play with [notero](https://github.com/dvanoni/notero) extension. Works surprisingly smooth.\n\nTo wrap up, there are more efficient workflows than relying solely on a Word database or gathering references in a single designated file. And they may be integrated with your favorite applications\n\n[^1]: That's the one tag which supposedly is a river and doesn't match to other apps listed.\n[^2]: I was thinking if there may be an extension using other, less legal sources. Yep, they exist.\n[^3]: Zotero has much more colors to highlight text.\n[^4]: While PDF support in Zotero is superior, I was mainly taking notes from websites where hypothesis were better. Look in further sources section for great review of note-taking tools.\n[^5]: Sharing is caring, or something like that.","src/content/thoughts/en/2023/08/zotero-experience.md","21a66278b9451592",{html:93,metadata:94},"<p><em>It’s an old note, just for archival purposes. There might be newer alternatives. Also, old blog template used another method of referencing urls, don’t have it yet here, so leaving it as-is: <a href=\"%22https://beepb00p.xyz/annotating.html%22\">link</a></em></p>\n<p>I have a need to share how much I love <a href=\"https://www.zotero.org/\">Zotero</a>. It was a tool that was a significant part of my academic journey and I had fallen in love while I was writing my B.Sc. thesis<sup><a href=\"#user-content-fn-1\" id=\"user-content-fnref-1\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">1</a></sup>, and all coexisting add-ons were indirectly responsible for about 50 references mentioned. I’ve recently also incorporated Zotero into my workflow alongside another side-project on Notion.</p>\n<p>Other remarkable features that Zotero offers:</p>\n<ul>\n<li>Awesome notes on existing PDFs. A bit better than <a href=\"https://web.hypothes.is/\">hypothes.is</a><sup><a href=\"#user-content-fn-3\" id=\"user-content-fnref-3\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">2</a></sup> what was my main driver in B.Sc. era for taking notes from PDFs.<sup><a href=\"#user-content-fn-4\" id=\"user-content-fnref-4\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">3</a></sup></li>\n<li>Collection mechanism - it’s a bit specific approach for zotero and needs time to be used to.</li>\n<li>Group collections that you can share your findings in teams.<sup><a href=\"#user-content-fn-5\" id=\"user-content-fnref-5\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">4</a></sup></li>\n</ul>\n<p>What add-ons were helpful?</p>\n<h2 id=\"firefox-extension\">Firefox extension</h2>\n<p><a href=\"https://www.zotero.org/download/connectors\">Zotero Connector for Firefox</a> simplifies the process of adding new database entries. A single click can trigger metadata extraction, and in some cases, even full-text PDF retrieval.<sup><a href=\"#user-content-fn-2\" id=\"user-content-fnref-2\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">5</a></sup></p>\n<h2 id=\"better-bibtex\">Better Bibtex</h2>\n<p><a href=\"https://retorque.re/zotero-better-bibtex/\">Better Bibtex</a> allows exporting yours database in format compatible with Latex.</p>\n<h3 id=\"only-latex\">Only Latex?</h3>\n<p>If you need a place to take notes and mention/link your entries, <a href=\"https://obsidian.md/\">Obsidian</a> might be a good place to start. There is a great tutorial that was a great inspiration, available <a href=\"vhttps://medium.com/@alexandraphelan/an-academic-workflow-zotero-obsidian-56bf918d51ab\">here</a>.</p>\n<p>There is a newer approach, however, that might work a bit better - <a href=\"https://github.com/PKM-er/obsidian-zotero\">Obsidian Zotero Plugin</a>. Haven’t tested yet.</p>\n<h2 id=\"but-what-if-i-want-to-share-my-zotero-based-entries-with-friends\">But what if I want to share my zotero-based entries with friends?</h2>\n<p>Sometime tool just doesn’t suit well, and forcing others to use obsidian might be imposing useless cognitive overload, so then Notion comes into play with <a href=\"https://github.com/dvanoni/notero\">notero</a> extension. Works surprisingly smooth.</p>\n<p>To wrap up, there are more efficient workflows than relying solely on a Word database or gathering references in a single designated file. And they may be integrated with your favorite applications</p>\n<section data-footnotes=\"\" class=\"footnotes\"><h2 class=\"\" id=\"footnote-label\">Footnotes</h2>\n<ol>\n<li id=\"user-content-fn-1\">\n<p>That’s the one tag which supposedly is a river and doesn’t match to other apps listed. <a href=\"#user-content-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-fn-3\">\n<p>Zotero has much more colors to highlight text. <a href=\"#user-content-fnref-3\" data-footnote-backref=\"\" aria-label=\"Back to reference 2\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-fn-4\">\n<p>While PDF support in Zotero is superior, I was mainly taking notes from websites where hypothesis were better. Look in further sources section for great review of note-taking tools. <a href=\"#user-content-fnref-4\" data-footnote-backref=\"\" aria-label=\"Back to reference 3\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-fn-5\">\n<p>Sharing is caring, or something like that. <a href=\"#user-content-fnref-5\" data-footnote-backref=\"\" aria-label=\"Back to reference 4\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-fn-2\">\n<p>I was thinking if there may be an extension using other, less legal sources. Yep, they exist. <a href=\"#user-content-fnref-2\" data-footnote-backref=\"\" aria-label=\"Back to reference 5\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",{headings:95,localImagePaths:109,remoteImagePaths:110,frontmatter:111,imagePaths:116},[96,99,102,105,108],{depth:28,slug:97,text:98},"firefox-extension","Firefox extension",{depth:28,slug:100,text:101},"better-bibtex","Better Bibtex",{depth:66,slug:103,text:104},"only-latex","Only Latex?",{depth:28,slug:106,text:107},"but-what-if-i-want-to-share-my-zotero-based-entries-with-friends","But what if I want to share my zotero-based entries with friends?",{depth:28,slug:29,text:30},[],[],{title:80,description:112,date:113,tags:114,previewHtml:115},"Short review of useful Zotero plugins.",["Date","2023-08-29T02:13:17.000Z"],[83,84,85,86,87,88],"<p><em>It’s an old note, just for archival purposes. There might be newer alternatives. Also, old blog template used another method of referencing urls, don’t have it yet here, so leaving it as-is: <a href=\"%22https://beepb00p.xyz/annotating.html%22\">link</a></em></p>\n<p>I have a need to share how much I love <a href=\"https://www.zotero.org/\">Zotero</a>. It was a tool that was a significant part of my academic journey and I had fallen in love while I was writing my B.Sc. thesis<sup><a href=\"#user-content-en-2023-08-zotero-experience-fn-1\" id=\"user-content-en-2023-08-zotero-experience-fnref-1\" data-footnote-ref aria-describedby=\"footnote-label\">1</a></sup>, and all coexisting add-ons were indirectly responsible for about 50 references mentioned. I’ve recently also incorporated Zotero into my workflow alongside another side-project on Notion.</p>\n<p>Other remarkable features that Zotero offers:</p>\n<ul>\n<li>Awesome notes on existing PDFs. A bit better than <a href=\"https://web.hypothes.is/\">hypothes.is</a><sup><a href=\"#user-content-en-2023-08-zotero-experience-fn-3\" id=\"user-content-en-2023-08-zotero-experience-fnref-3\" data-footnote-ref aria-describedby=\"footnote-label\">2</a></sup> what was my main driver in B.Sc. era for taking notes from PDFs.<sup><a href=\"#user-content-en-2023-08-zotero-experience-fn-4\" id=\"user-content-en-2023-08-zotero-experience-fnref-4\" data-footnote-ref aria-describedby=\"footnote-label\">3</a></sup></li>\n<li>Collection mechanism - it’s a bit specific approach for zotero and needs time to be used to.</li>\n<li>Group collections that you can share your findings in teams.<sup><a href=\"#user-content-en-2023-08-zotero-experience-fn-5\" id=\"user-content-en-2023-08-zotero-experience-fnref-5\" data-footnote-ref aria-describedby=\"footnote-label\">4</a></sup></li>\n</ul>\n<p>What add-ons were helpful?</p>\n<h2>Firefox extension</h2>\n<p><a href=\"https://www.zotero.org/download/connectors\">Zotero Connector for Firefox</a> simplifies the process of adding new database entries. A single click can trigger metadata extraction, and in some cases, even full-text PDF retrieval.<sup><a href=\"#user-content-en-2023-08-zotero-experience-fn-2\" id=\"user-content-en-2023-08-zotero-experience-fnref-2\" data-footnote-ref aria-describedby=\"footnote-label\">5</a></sup></p>\n<h2>Better Bibtex</h2>\n<p><a href=\"https://retorque.re/zotero-better-bibtex/\">Better Bibtex</a> allows exporting yours database in format compatible with Latex.</p>\n<h3>Only Latex?</h3>\n<p>If you need a place to take notes and mention/link your entries, <a href=\"https://obsidian.md/\">Obsidian</a> might be a good place to start. There is a great tutorial that was a great inspiration, available <a href=\"vhttps://medium.com/@alexandraphelan/an-academic-workflow-zotero-obsidian-56bf918d51ab\">here</a>.</p>\n<p>There is a newer approach, however, that might work a bit better - <a href=\"https://github.com/PKM-er/obsidian-zotero\">Obsidian Zotero Plugin</a>. Haven’t tested yet.</p>\n<h2>But what if I want to share my zotero-based entries with friends?</h2>\n<p>Sometime tool just doesn’t suit well, and forcing others to use obsidian might be imposing useless cognitive overload, so then Notion comes into play with <a href=\"https://github.com/dvanoni/notero\">notero</a> extension. Works surprisingly smooth.</p>\n<p>To wrap up, there are more efficient workflows than relying solely on a Word database or gathering references in a single designated file. And they may be integrated with your favorite applications</p>\n<section data-footnotes class=\"footnotes\"><h2 class=\"sr-only\" id=\"footnote-label\">Footnotes</h2>\n<ol>\n<li id=\"user-content-en-2023-08-zotero-experience-fn-1\">\n<p>That’s the one tag which supposedly is a river and doesn’t match to other apps listed. <a href=\"#user-content-en-2023-08-zotero-experience-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-en-2023-08-zotero-experience-fn-3\">\n<p>Zotero has much more colors to highlight text. <a href=\"#user-content-en-2023-08-zotero-experience-fnref-3\" data-footnote-backref=\"\" aria-label=\"Back to reference 2\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-en-2023-08-zotero-experience-fn-4\">\n<p>While PDF support in Zotero is superior, I was mainly taking notes from websites where hypothesis were better. Look in further sources section for great review of note-taking tools. <a href=\"#user-content-en-2023-08-zotero-experience-fnref-4\" data-footnote-backref=\"\" aria-label=\"Back to reference 3\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-en-2023-08-zotero-experience-fn-5\">\n<p>Sharing is caring, or something like that. <a href=\"#user-content-en-2023-08-zotero-experience-fnref-5\" data-footnote-backref=\"\" aria-label=\"Back to reference 4\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-en-2023-08-zotero-experience-fn-2\">\n<p>I was thinking if there may be an extension using other, less legal sources. Yep, they exist. <a href=\"#user-content-en-2023-08-zotero-experience-fnref-2\" data-footnote-backref=\"\" aria-label=\"Back to reference 5\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",[],"en/2026/04/looking-for-aaaaa-rave",{id:117,data:119,body:124,filePath:125,assetImports:126,digest:128,rendered:129},{title:120,date:121,tags:122,translationKey:123,draft:19},"Looking for AAAAA Rave",["Date","2026-04-27T00:00:00.000Z"],[],"aaaaa-rave-szukam-2026-04","# Looking for AAAAA Rave\n\n![Resident Advisor](@assets/images/resident-advisor.png \"Search results on Resident Advisor for Poland, April 2026\")\n\nHello world.","src/content/thoughts/en/2026/04/looking-for-aaaaa-rave.md",[127],"../../../../../assets/images/resident-advisor.png","92280d9efbda4164",{html:130,metadata:131},"<h1 id=\"looking-for-aaaaa-rave\">Looking for AAAAA Rave</h1>\n<p></p><figure class=\"post-figure\"><img __ASTRO_IMAGE_=\"{&#x22;src&#x22;:&#x22;../../../../../assets/images/resident-advisor.png&#x22;,&#x22;alt&#x22;:&#x22;Resident Advisor&#x22;,&#x22;index&#x22;:0}\"><figcaption>Search results on Resident Advisor for Poland, April 2026</figcaption></figure><p></p>\n<p>Hello world.</p>",{headings:132,localImagePaths:136,remoteImagePaths:137,frontmatter:138,imagePaths:142},[133],{depth:134,slug:135,text:120},1,"looking-for-aaaaa-rave",[127],[],{title:120,date:139,tags:140,translationKey:123,draft:19,lang:37,previewHtml:141},["Date","2026-04-27T00:00:00.000Z"],[],"<h1>Looking for AAAAA Rave</h1>\n<p><figure class=\"post-figure\"><img src=\"/__preview_asset__/assets/images/resident-advisor.png\" alt=\"Resident Advisor\"><figcaption>Search results on Resident Advisor for Poland, April 2026</figcaption></figure></p>\n<p>Hello world.</p>",[127],"pl/2025/12/jak-miec-multiscreen-na-azurowskim-bastionie",{id:143,data:145,body:152,filePath:153,digest:154,rendered:155},{title:146,date:147,tags:148,draft:51},"Jak mieć multiscreen na Azurowskim Bastionie?",["Date","2025-12-08T20:01:36.641Z"],[149,150,151,50],"Azure","Cloud","Tech","Ostatnio dość dużo czasu spędzam na Azure - ich webowy klient działa dość topornie - na szczęście, trafiłem na rozwiązanie: [az(Azure CLI) ma dodatek, który pozwala wyprowadzić RDP aby łączyć się na serwer natywnym kliencie](https://www.terminalworks.com/blog/post/2024/11/23/azure-bastion-use-of-native-client-for-windows).\n\nWarto też wspomnieć że Microsoft w swej dobroci wrzuca az jako [zip do ściągnięcia](https://learn.microsoft.com/en-us/cli/azure/install-azure-cli-windows?view=azure-cli-latest&pivots=zip) - w sam raz na środowiska gdzie brakuje praw administratora[^1].\n\n[^1]: Gdyby was kusiło budować samemu  na lokalnym pythonie - bez ~~bez kraka nie pójdzie~~ większej ilości narzdzi do budowania - a w Condzie też nie działał.","src/content/thoughts/pl/2025/12/jak-miec-multiscreen-na-azurowskim-bastionie.md","fb450bbb6f483050",{html:156,metadata:157},"<p>Ostatnio dość dużo czasu spędzam na Azure - ich webowy klient działa dość topornie - na szczęście, trafiłem na rozwiązanie: <a href=\"https://www.terminalworks.com/blog/post/2024/11/23/azure-bastion-use-of-native-client-for-windows\">az(Azure CLI) ma dodatek, który pozwala wyprowadzić RDP aby łączyć się na serwer natywnym kliencie</a>.</p>\n<p>Warto też wspomnieć że Microsoft w swej dobroci wrzuca az jako <a href=\"https://learn.microsoft.com/en-us/cli/azure/install-azure-cli-windows?view=azure-cli-latest&#x26;pivots=zip\">zip do ściągnięcia</a> - w sam raz na środowiska gdzie brakuje praw administratora<sup><a href=\"#user-content-fn-1\" id=\"user-content-fnref-1\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">1</a></sup>.</p>\n<section data-footnotes=\"\" class=\"footnotes\"><h2 class=\"\" id=\"footnote-label\">Przypisy</h2>\n<ol>\n<li id=\"user-content-fn-1\">\n<p>Gdyby was kusiło budować samemu  na lokalnym pythonie - bez <del>bez kraka nie pójdzie</del> większej ilości narzdzi do budowania - a w Condzie też nie działał. <a href=\"#user-content-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",{headings:158,localImagePaths:161,remoteImagePaths:162,frontmatter:163,imagePaths:168},[159],{depth:28,slug:29,text:160},"Przypisy",[],[],{title:146,date:164,tags:165,draft:51,lang:166,previewHtml:167},["Date","2025-12-08T20:01:36.641Z"],[149,150,151,50],"pl","<p>Ostatnio dość dużo czasu spędzam na Azure - ich webowy klient działa dość topornie - na szczęście, trafiłem na rozwiązanie: <a href=\"https://www.terminalworks.com/blog/post/2024/11/23/azure-bastion-use-of-native-client-for-windows\">az(Azure CLI) ma dodatek, który pozwala wyprowadzić RDP aby łączyć się na serwer natywnym kliencie</a>.</p>\n<p>Warto też wspomnieć że Microsoft w swej dobroci wrzuca az jako <a href=\"https://learn.microsoft.com/en-us/cli/azure/install-azure-cli-windows?view=azure-cli-latest&#x26;pivots=zip\">zip do ściągnięcia</a> - w sam raz na środowiska gdzie brakuje praw administratora<sup><a href=\"#user-content-pl-2025-12-jak-miec-multiscreen-na-azurowskim-bastionie-fn-1\" id=\"user-content-pl-2025-12-jak-miec-multiscreen-na-azurowskim-bastionie-fnref-1\" data-footnote-ref aria-describedby=\"footnote-label\">1</a></sup>.</p>\n<section data-footnotes class=\"footnotes\"><h2 class=\"sr-only\" id=\"footnote-label\">Footnotes</h2>\n<ol>\n<li id=\"user-content-pl-2025-12-jak-miec-multiscreen-na-azurowskim-bastionie-fn-1\">\n<p>Gdyby was kusiło budować samemu  na lokalnym pythonie - bez <del>bez kraka nie pójdzie</del> większej ilości narzdzi do budowania - a w Condzie też nie działał. <a href=\"#user-content-pl-2025-12-jak-miec-multiscreen-na-azurowskim-bastionie-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",[],"pl/2024/06/dpd-a-przesylki",{id:169,data:171,body:179,filePath:180,digest:181,rendered:182},{title:172,date:173,tags:174,draft:51},"DPD a przesyłki - jak poprawić jakość niskim kosztem?",["Date","2024-06-13T00:00:00.000Z"],[175,176,177,178],"Typ/insight","Protipy","Kurierzy","DPD","Nie, żebym samemu miał bardzo nieprzyjemne doświadczenie ze składaniem reklamacji w DPD, dlatego ten protip przeklejam z przyjemnością:\n \n>Ten magiczny \"podpis\", widoczny jako odbiorca w statusie to przepisanie nazwiska z listu na zebrze przy zatwierdzaniu. Fizycznych podpisów kurierzy nie zbierają od czasów covida. Jeśli mirek chciał do rąk odbiorcy, mógł dopłacić DPD za usługę DRW[^1] z pinem, wtedy kurier nie wrzuci takiej paczki za płot, bo będzie musiał wpisać pin od odbiorcy, żeby dobić ją w systemie. Ot cała magia.\n\n[Źródło.](https://wykop.pl/link/7465835/dpd-przerzuca-komputer-przez-plot-niszczy-go-i-bezczelnie-odrzuca-reklamacje/komentarz/124712141/na-dodatek-w-systemie-paczka-widnieje-jako-odebrana-i-podpisana-od-paru-lat-kurierzy-nie-wymagaja-podpisow-po-prostu-paczka-laduje-gdziekolwiek-pod-ty#124712705)\n\n[^1]: Do Rąk Własnych","src/content/thoughts/pl/2024/06/dpd-a-przesylki.md","12eb9ff75ecf8749",{html:183,metadata:184},"<p>Nie, żebym samemu miał bardzo nieprzyjemne doświadczenie ze składaniem reklamacji w DPD, dlatego ten protip przeklejam z przyjemnością:</p>\n<blockquote>\n<p>Ten magiczny “podpis”, widoczny jako odbiorca w statusie to przepisanie nazwiska z listu na zebrze przy zatwierdzaniu. Fizycznych podpisów kurierzy nie zbierają od czasów covida. Jeśli mirek chciał do rąk odbiorcy, mógł dopłacić DPD za usługę DRW<sup><a href=\"#user-content-fn-1\" id=\"user-content-fnref-1\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">1</a></sup> z pinem, wtedy kurier nie wrzuci takiej paczki za płot, bo będzie musiał wpisać pin od odbiorcy, żeby dobić ją w systemie. Ot cała magia.</p>\n</blockquote>\n<p><a href=\"https://wykop.pl/link/7465835/dpd-przerzuca-komputer-przez-plot-niszczy-go-i-bezczelnie-odrzuca-reklamacje/komentarz/124712141/na-dodatek-w-systemie-paczka-widnieje-jako-odebrana-i-podpisana-od-paru-lat-kurierzy-nie-wymagaja-podpisow-po-prostu-paczka-laduje-gdziekolwiek-pod-ty#124712705\">Źródło.</a></p>\n<section data-footnotes=\"\" class=\"footnotes\"><h2 class=\"\" id=\"footnote-label\">Przypisy</h2>\n<ol>\n<li id=\"user-content-fn-1\">\n<p>Do Rąk Własnych <a href=\"#user-content-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",{headings:185,localImagePaths:187,remoteImagePaths:188,frontmatter:189,imagePaths:196},[186],{depth:28,slug:29,text:160},[],[],{title:172,draft:51,tags:190,aliases:191,date:193,description:194,previewHtml:195},[175,176,177,178],[192],"DPD a przesyłki",["Date","2024-06-13T00:00:00.000Z"],"Jak prostym trikiem sprawić że paczka jednak zobaczy odbiorcę?","<p>Nie, żebym samemu miał bardzo nieprzyjemne doświadczenie ze składaniem reklamacji w DPD, dlatego ten protip przeklejam z przyjemnością:</p>\n<blockquote>\n<p>Ten magiczny “podpis”, widoczny jako odbiorca w statusie to przepisanie nazwiska z listu na zebrze przy zatwierdzaniu. Fizycznych podpisów kurierzy nie zbierają od czasów covida. Jeśli mirek chciał do rąk odbiorcy, mógł dopłacić DPD za usługę DRW<sup><a href=\"#user-content-pl-2024-06-dpd-a-przesylki-fn-1\" id=\"user-content-pl-2024-06-dpd-a-przesylki-fnref-1\" data-footnote-ref aria-describedby=\"footnote-label\">1</a></sup> z pinem, wtedy kurier nie wrzuci takiej paczki za płot, bo będzie musiał wpisać pin od odbiorcy, żeby dobić ją w systemie. Ot cała magia.</p>\n</blockquote>\n<p><a href=\"https://wykop.pl/link/7465835/dpd-przerzuca-komputer-przez-plot-niszczy-go-i-bezczelnie-odrzuca-reklamacje/komentarz/124712141/na-dodatek-w-systemie-paczka-widnieje-jako-odebrana-i-podpisana-od-paru-lat-kurierzy-nie-wymagaja-podpisow-po-prostu-paczka-laduje-gdziekolwiek-pod-ty#124712705\">Źródło.</a></p>\n<section data-footnotes class=\"footnotes\"><h2 class=\"sr-only\" id=\"footnote-label\">Footnotes</h2>\n<ol>\n<li id=\"user-content-pl-2024-06-dpd-a-przesylki-fn-1\">\n<p>Do Rąk Własnych <a href=\"#user-content-pl-2024-06-dpd-a-przesylki-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",[],"pl/2024/06/jak-wrocic-z-amsterdamu",{id:197,data:199,body:207,filePath:208,digest:209,rendered:210},{title:200,date:201,tags:202,draft:51},"Jak wrócić z amsterdamu",["Date","2024-07-07T00:00:00.000Z"],[203,204,205,206],"Pociągi","Podróże","Europa","Transport","Podejmując skądinąd odważną decyzję o wyprawie na  Dominator 2024 i urozmaicając to wypadem do Amsterdamu, pozostaje jeszcze wątek *jak wrócić?*\n\n## Warunki brzegowe\n\nZakładam że po całym poniedziałku w Amsterdamie zaczyna się wątek powrotu - czyli do dyspozycji jest albo nocny pociąg, albo  nocleg + powrót cały dzień albo dzień przesiadkowy w innej europejskiej stolicy.\n\nWszystkie ceny są na dzień dzisiejszy, 07.07.24, planowane trochę do przodu tj. ten poniedziałek to 22.07. Ceny uwzględniają powrót do Olsztyna, gdzie aplikowalne, tam ze żniżką 37% w polskim PKP. \n# Pociągi nocne\n\nZ tego co widzę, żeby koszty noclegu połączyć z kosztami transportu są takie opcje:\n\n## Berlin\n\nNa czas tworzenia tego postu #ChatGPT  podpowiedziało mi o istnieniu [European Sleeper](https://www.europeansleeper.eu/) , czyli jakimś reboocie pociągów sypialnianych[^1]. Jedyne dostępne na dziś połączenie to komfortowe kuszetki.\n\n\n| Pozycja                       | EUR |\n| ----------------------------- | --- |\n| Nocny z Amsterdamu do Berlina | 159 |\n### Dlaczego Berlin to zła opcja *na ten konkretny wyjazd*?\n\nJakkolwiek dawien dawno chodząc po Warszawie Centralnej z pewnym rozmarzeniem spoglądałem na Berlin-Warszawa-Express zastanawiając się czy kiedykolwiek nim pojadę, to 23.07 zaczyna się remont linii RE1, przez co całość  trochę  mija się z celem - z drugiej strony jest też opcja powrotu przez Szczecin, gdzie busa jest mniej, ale..nie jestem przekonany. \n\n## Praga\nW tym samym ES jest też możliwość dotarcia do Pragi, kolejna pozycja to EN z pragi do Warszawy i powrót z Warszawy do Olsztyna[^2]\n\n\n| Pozycja           | EUR | PLN     |\n| ----------------- | --- | ------- |\n| ES                | 179 | ~767,33 |\n| EN Praga-Warszawa |     | 196,66  |\n| Warszawa-Olsztyn  |     | 16,36   |\n| Suma              |     | 980,35  |\n\n## Monachium\n\n| Pozycja                | EUR    | PLN    |\n| ---------------------- | ------ | ------ |\n| EN Amsterdam-Monachium | 105,50 | 452,25 |\n| EN Monachium-Warszawa  |        | 437,56 |\n| Warszawa-Olsztyn       |        | 16,36  |\n| Suma                   |        | 906,17 |\n\n## Drezno\n\nInspiracja z przedziaławki - podróż European Sleeperem do Drezna, stamtąd przesiadka do Zgorzelca, a stamtąd przesiadka we Wrocławiu. Szczerze? Jak spojrzałem na tą propozycję - stwierdziłem że już jestem za stary na takie zabawy. \n\n| Pozycja             | EUR   | PLN    |\n| ------------------- | ----- | ------ |\n| ES                  | 179   | 767,33 |\n| Drezno - Zgorzelec  | 34,90 | 149,61 |\n| Zgorzelec - Wrocław |       | 20,40  |\n| Wrocław-Olsztyn     |       | 49,77  |\n\n\n## Wiedeń\n\nAkurat te bilety na ten euronight zostały wyprzedane(a szkoda). W każdym razie intercity promo ma na tej trasie praskie ceny - około 200zł.\n\n\n## Połączenia mieszane\n\n## Hamburg\n\nPod rozwagę gdyby ktoś szukał inspiracji zostawiam że loty z Hamburga bywają znacznie tańsze niż z Amsterdamu - mnie odstraszyła głównie dopłata za bagaż podręczny[^3]. Jest tak blisko do Amsterdamu, że nie ma żadnych nocnych \n\n## Dortmund\n\nRozważając kiedyś wyjazd na jeden festiwal gdzie [[Ophidian]] grał, zwróciłem uwagę na to że któraś z tanich linii lotniczy miała tanie połączenie z [[Lotnisko Szymany]].  Niestety, połączenia zostały zawieszone.\n## Eindhoven\n\nStamtąd moja podróż się zaczynała, dlatego nie miałem ochoty za bardzo wracać[^4] - zresztą ceny biletów nie były jakieś szczególnie przystępne.\n# Inne rozwiązania\n\n## Flixbus z Berlina \nZa około 200zł jest 11h powrotu autokarem do Olsztyna. \n\n# Podsumowanie\n\nZdecydowałem się na powrót przez Monachium. Muzeum BMW, duże parki i bodajże fajne muzea ze sztuką brzmią jak fajny pomysł na dzień.\n\n[^1]: Umykały mi te połączenia z powodu że nie startują z Amsterdam Centraal, tylko jakiegoś innego połączenia. \n[^2]: Też jestem pod wrażeniem jakie niesamowite zniżki mi wchodzą, ale to w większości efekt kupowania porannego biletu z ogromnym wyprzedzeniem chyba.\n[^3]: Który i tak mam wrażenie że wziąłem na siłę na te kilka dni.\n[^4]: #ADHD thing, aby wciąż do przodu i wciąż doświadczań nowych bodżców.","src/content/thoughts/pl/2024/06/jak-wrocic-z-amsterdamu.md","b5e1cf285f7e04a9",{html:211,metadata:212},"<p>Podejmując skądinąd odważną decyzję o wyprawie na  Dominator 2024 i urozmaicając to wypadem do Amsterdamu, pozostaje jeszcze wątek <em>jak wrócić?</em></p>\n<h2 id=\"warunki-brzegowe\">Warunki brzegowe</h2>\n<p>Zakładam że po całym poniedziałku w Amsterdamie zaczyna się wątek powrotu - czyli do dyspozycji jest albo nocny pociąg, albo  nocleg + powrót cały dzień albo dzień przesiadkowy w innej europejskiej stolicy.</p>\n<p>Wszystkie ceny są na dzień dzisiejszy, 07.07.24, planowane trochę do przodu tj. ten poniedziałek to 22.07. Ceny uwzględniają powrót do Olsztyna, gdzie aplikowalne, tam ze żniżką 37% w polskim PKP.</p>\n<h1 id=\"pociągi-nocne\">Pociągi nocne</h1>\n<p>Z tego co widzę, żeby koszty noclegu połączyć z kosztami transportu są takie opcje:</p>\n<h2 id=\"berlin\">Berlin</h2>\n<p>Na czas tworzenia tego postu #ChatGPT  podpowiedziało mi o istnieniu <a href=\"https://www.europeansleeper.eu/\">European Sleeper</a> , czyli jakimś reboocie pociągów sypialnianych<sup><a href=\"#user-content-fn-1\" id=\"user-content-fnref-1\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">1</a></sup>. Jedyne dostępne na dziś połączenie to komfortowe kuszetki.</p>\n\n\n\n\n\n\n\n\n\n\n\n\n\n<table><thead><tr><th>Pozycja</th><th>EUR</th></tr></thead><tbody><tr><td>Nocny z Amsterdamu do Berlina</td><td>159</td></tr></tbody></table>\n<h3 id=\"dlaczego-berlin-to-zła-opcja-na-ten-konkretny-wyjazd\">Dlaczego Berlin to zła opcja <em>na ten konkretny wyjazd</em>?</h3>\n<p>Jakkolwiek dawien dawno chodząc po Warszawie Centralnej z pewnym rozmarzeniem spoglądałem na Berlin-Warszawa-Express zastanawiając się czy kiedykolwiek nim pojadę, to 23.07 zaczyna się remont linii RE1, przez co całość  trochę  mija się z celem - z drugiej strony jest też opcja powrotu przez Szczecin, gdzie busa jest mniej, ale..nie jestem przekonany.</p>\n<h2 id=\"praga\">Praga</h2>\n<p>W tym samym ES jest też możliwość dotarcia do Pragi, kolejna pozycja to EN z pragi do Warszawy i powrót z Warszawy do Olsztyna<sup><a href=\"#user-content-fn-2\" id=\"user-content-fnref-2\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">2</a></sup></p>\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n<table><thead><tr><th>Pozycja</th><th>EUR</th><th>PLN</th></tr></thead><tbody><tr><td>ES</td><td>179</td><td>~767,33</td></tr><tr><td>EN Praga-Warszawa</td><td></td><td>196,66</td></tr><tr><td>Warszawa-Olsztyn</td><td></td><td>16,36</td></tr><tr><td>Suma</td><td></td><td>980,35</td></tr></tbody></table>\n<h2 id=\"monachium\">Monachium</h2>\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n<table><thead><tr><th>Pozycja</th><th>EUR</th><th>PLN</th></tr></thead><tbody><tr><td>EN Amsterdam-Monachium</td><td>105,50</td><td>452,25</td></tr><tr><td>EN Monachium-Warszawa</td><td></td><td>437,56</td></tr><tr><td>Warszawa-Olsztyn</td><td></td><td>16,36</td></tr><tr><td>Suma</td><td></td><td>906,17</td></tr></tbody></table>\n<h2 id=\"drezno\">Drezno</h2>\n<p>Inspiracja z przedziaławki - podróż European Sleeperem do Drezna, stamtąd przesiadka do Zgorzelca, a stamtąd przesiadka we Wrocławiu. Szczerze? Jak spojrzałem na tą propozycję - stwierdziłem że już jestem za stary na takie zabawy.</p>\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n<table><thead><tr><th>Pozycja</th><th>EUR</th><th>PLN</th></tr></thead><tbody><tr><td>ES</td><td>179</td><td>767,33</td></tr><tr><td>Drezno - Zgorzelec</td><td>34,90</td><td>149,61</td></tr><tr><td>Zgorzelec - Wrocław</td><td></td><td>20,40</td></tr><tr><td>Wrocław-Olsztyn</td><td></td><td>49,77</td></tr></tbody></table>\n<h2 id=\"wiedeń\">Wiedeń</h2>\n<p>Akurat te bilety na ten euronight zostały wyprzedane(a szkoda). W każdym razie intercity promo ma na tej trasie praskie ceny - około 200zł.</p>\n<h2 id=\"połączenia-mieszane\">Połączenia mieszane</h2>\n<h2 id=\"hamburg\">Hamburg</h2>\n<p>Pod rozwagę gdyby ktoś szukał inspiracji zostawiam że loty z Hamburga bywają znacznie tańsze niż z Amsterdamu - mnie odstraszyła głównie dopłata za bagaż podręczny<sup><a href=\"#user-content-fn-3\" id=\"user-content-fnref-3\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">3</a></sup>. Jest tak blisko do Amsterdamu, że nie ma żadnych nocnych</p>\n<h2 id=\"dortmund\">Dortmund</h2>\n<p>Rozważając kiedyś wyjazd na jeden festiwal gdzie [[Ophidian]] grał, zwróciłem uwagę na to że któraś z tanich linii lotniczy miała tanie połączenie z [[Lotnisko Szymany]].  Niestety, połączenia zostały zawieszone.</p>\n<h2 id=\"eindhoven\">Eindhoven</h2>\n<p>Stamtąd moja podróż się zaczynała, dlatego nie miałem ochoty za bardzo wracać<sup><a href=\"#user-content-fn-4\" id=\"user-content-fnref-4\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">4</a></sup> - zresztą ceny biletów nie były jakieś szczególnie przystępne.</p>\n<h1 id=\"inne-rozwiązania\">Inne rozwiązania</h1>\n<h2 id=\"flixbus-z-berlina\">Flixbus z Berlina</h2>\n<p>Za około 200zł jest 11h powrotu autokarem do Olsztyna.</p>\n<h1 id=\"podsumowanie\">Podsumowanie</h1>\n<p>Zdecydowałem się na powrót przez Monachium. Muzeum BMW, duże parki i bodajże fajne muzea ze sztuką brzmią jak fajny pomysł na dzień.</p>\n<section data-footnotes=\"\" class=\"footnotes\"><h2 class=\"\" id=\"footnote-label\">Przypisy</h2>\n<ol>\n<li id=\"user-content-fn-1\">\n<p>Umykały mi te połączenia z powodu że nie startują z Amsterdam Centraal, tylko jakiegoś innego połączenia. <a href=\"#user-content-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-fn-2\">\n<p>Też jestem pod wrażeniem jakie niesamowite zniżki mi wchodzą, ale to w większości efekt kupowania porannego biletu z ogromnym wyprzedzeniem chyba. <a href=\"#user-content-fnref-2\" data-footnote-backref=\"\" aria-label=\"Back to reference 2\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-fn-3\">\n<p>Który i tak mam wrażenie że wziąłem na siłę na te kilka dni. <a href=\"#user-content-fnref-3\" data-footnote-backref=\"\" aria-label=\"Back to reference 3\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-fn-4\">\n<p>#ADHD thing, aby wciąż do przodu i wciąż doświadczań nowych bodżców. <a href=\"#user-content-fnref-4\" data-footnote-backref=\"\" aria-label=\"Back to reference 4\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",{headings:213,localImagePaths:260,remoteImagePaths:261,frontmatter:262,imagePaths:267},[214,217,220,223,226,229,232,235,238,241,244,247,250,253,256,259],{depth:28,slug:215,text:216},"warunki-brzegowe","Warunki brzegowe",{depth:134,slug:218,text:219},"pociągi-nocne","Pociągi nocne",{depth:28,slug:221,text:222},"berlin","Berlin",{depth:66,slug:224,text:225},"dlaczego-berlin-to-zła-opcja-na-ten-konkretny-wyjazd","Dlaczego Berlin to zła opcja na ten konkretny wyjazd?",{depth:28,slug:227,text:228},"praga","Praga",{depth:28,slug:230,text:231},"monachium","Monachium",{depth:28,slug:233,text:234},"drezno","Drezno",{depth:28,slug:236,text:237},"wiedeń","Wiedeń",{depth:28,slug:239,text:240},"połączenia-mieszane","Połączenia mieszane",{depth:28,slug:242,text:243},"hamburg","Hamburg",{depth:28,slug:245,text:246},"dortmund","Dortmund",{depth:28,slug:248,text:249},"eindhoven","Eindhoven",{depth:134,slug:251,text:252},"inne-rozwiązania","Inne rozwiązania",{depth:28,slug:254,text:255},"flixbus-z-berlina","Flixbus z Berlina",{depth:134,slug:257,text:258},"podsumowanie","Podsumowanie",{depth:28,slug:29,text:160},[],[],{title:200,draft:51,tags:263,aliases:264,date:265,previewHtml:266},[203,204,205,206],[200],["Date","2024-07-07T00:00:00.000Z"],"<p>Podejmując skądinąd odważną decyzję o wyprawie na  Dominator 2024 i urozmaicając to wypadem do Amsterdamu, pozostaje jeszcze wątek <em>jak wrócić?</em></p>\n<h2>Warunki brzegowe</h2>\n<p>Zakładam że po całym poniedziałku w Amsterdamie zaczyna się wątek powrotu - czyli do dyspozycji jest albo nocny pociąg, albo  nocleg + powrót cały dzień albo dzień przesiadkowy w innej europejskiej stolicy.</p>\n<p>Wszystkie ceny są na dzień dzisiejszy, 07.07.24, planowane trochę do przodu tj. ten poniedziałek to 22.07. Ceny uwzględniają powrót do Olsztyna, gdzie aplikowalne, tam ze żniżką 37% w polskim PKP.</p>\n<h1>Pociągi nocne</h1>\n<p>Z tego co widzę, żeby koszty noclegu połączyć z kosztami transportu są takie opcje:</p>\n<h2>Berlin</h2>\n<p>Na czas tworzenia tego postu #ChatGPT  podpowiedziało mi o istnieniu <a href=\"https://www.europeansleeper.eu/\">European Sleeper</a> , czyli jakimś reboocie pociągów sypialnianych<sup><a href=\"#user-content-pl-2024-06-jak-wrocic-z-amsterdamu-fn-1\" id=\"user-content-pl-2024-06-jak-wrocic-z-amsterdamu-fnref-1\" data-footnote-ref aria-describedby=\"footnote-label\">1</a></sup>. Jedyne dostępne na dziś połączenie to komfortowe kuszetki.</p>\n<table>\n<thead>\n<tr>\n<th>Pozycja</th>\n<th>EUR</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Nocny z Amsterdamu do Berlina</td>\n<td>159</td>\n</tr>\n</tbody>\n</table>\n<h3>Dlaczego Berlin to zła opcja <em>na ten konkretny wyjazd</em>?</h3>\n<p>Jakkolwiek dawien dawno chodząc po Warszawie Centralnej z pewnym rozmarzeniem spoglądałem na Berlin-Warszawa-Express zastanawiając się czy kiedykolwiek nim pojadę, to 23.07 zaczyna się remont linii RE1, przez co całość  trochę  mija się z celem - z drugiej strony jest też opcja powrotu przez Szczecin, gdzie busa jest mniej, ale..nie jestem przekonany.</p>\n<h2>Praga</h2>\n<p>W tym samym ES jest też możliwość dotarcia do Pragi, kolejna pozycja to EN z pragi do Warszawy i powrót z Warszawy do Olsztyna<sup><a href=\"#user-content-pl-2024-06-jak-wrocic-z-amsterdamu-fn-2\" id=\"user-content-pl-2024-06-jak-wrocic-z-amsterdamu-fnref-2\" data-footnote-ref aria-describedby=\"footnote-label\">2</a></sup></p>\n<table>\n<thead>\n<tr>\n<th>Pozycja</th>\n<th>EUR</th>\n<th>PLN</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>ES</td>\n<td>179</td>\n<td>~767,33</td>\n</tr>\n<tr>\n<td>EN Praga-Warszawa</td>\n<td></td>\n<td>196,66</td>\n</tr>\n<tr>\n<td>Warszawa-Olsztyn</td>\n<td></td>\n<td>16,36</td>\n</tr>\n<tr>\n<td>Suma</td>\n<td></td>\n<td>980,35</td>\n</tr>\n</tbody>\n</table>\n<h2>Monachium</h2>\n<table>\n<thead>\n<tr>\n<th>Pozycja</th>\n<th>EUR</th>\n<th>PLN</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>EN Amsterdam-Monachium</td>\n<td>105,50</td>\n<td>452,25</td>\n</tr>\n<tr>\n<td>EN Monachium-Warszawa</td>\n<td></td>\n<td>437,56</td>\n</tr>\n<tr>\n<td>Warszawa-Olsztyn</td>\n<td></td>\n<td>16,36</td>\n</tr>\n<tr>\n<td>Suma</td>\n<td></td>\n<td>906,17</td>\n</tr>\n</tbody>\n</table>\n<h2>Drezno</h2>\n<p>Inspiracja z przedziaławki - podróż European Sleeperem do Drezna, stamtąd przesiadka do Zgorzelca, a stamtąd przesiadka we Wrocławiu. Szczerze? Jak spojrzałem na tą propozycję - stwierdziłem że już jestem za stary na takie zabawy.</p>\n<table>\n<thead>\n<tr>\n<th>Pozycja</th>\n<th>EUR</th>\n<th>PLN</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>ES</td>\n<td>179</td>\n<td>767,33</td>\n</tr>\n<tr>\n<td>Drezno - Zgorzelec</td>\n<td>34,90</td>\n<td>149,61</td>\n</tr>\n<tr>\n<td>Zgorzelec - Wrocław</td>\n<td></td>\n<td>20,40</td>\n</tr>\n<tr>\n<td>Wrocław-Olsztyn</td>\n<td></td>\n<td>49,77</td>\n</tr>\n</tbody>\n</table>\n<h2>Wiedeń</h2>\n<p>Akurat te bilety na ten euronight zostały wyprzedane(a szkoda). W każdym razie intercity promo ma na tej trasie praskie ceny - około 200zł.</p>\n<h2>Połączenia mieszane</h2>\n<h2>Hamburg</h2>\n<p>Pod rozwagę gdyby ktoś szukał inspiracji zostawiam że loty z Hamburga bywają znacznie tańsze niż z Amsterdamu - mnie odstraszyła głównie dopłata za bagaż podręczny<sup><a href=\"#user-content-pl-2024-06-jak-wrocic-z-amsterdamu-fn-3\" id=\"user-content-pl-2024-06-jak-wrocic-z-amsterdamu-fnref-3\" data-footnote-ref aria-describedby=\"footnote-label\">3</a></sup>. Jest tak blisko do Amsterdamu, że nie ma żadnych nocnych</p>\n<h2>Dortmund</h2>\n<p>Rozważając kiedyś wyjazd na jeden festiwal gdzie [[Ophidian]] grał, zwróciłem uwagę na to że któraś z tanich linii lotniczy miała tanie połączenie z [[Lotnisko Szymany]].  Niestety, połączenia zostały zawieszone.</p>\n<h2>Eindhoven</h2>\n<p>Stamtąd moja podróż się zaczynała, dlatego nie miałem ochoty za bardzo wracać<sup><a href=\"#user-content-pl-2024-06-jak-wrocic-z-amsterdamu-fn-4\" id=\"user-content-pl-2024-06-jak-wrocic-z-amsterdamu-fnref-4\" data-footnote-ref aria-describedby=\"footnote-label\">4</a></sup> - zresztą ceny biletów nie były jakieś szczególnie przystępne.</p>\n<h1>Inne rozwiązania</h1>\n<h2>Flixbus z Berlina</h2>\n<p>Za około 200zł jest 11h powrotu autokarem do Olsztyna.</p>\n<h1>Podsumowanie</h1>\n<p>Zdecydowałem się na powrót przez Monachium. Muzeum BMW, duże parki i bodajże fajne muzea ze sztuką brzmią jak fajny pomysł na dzień.</p>\n<section data-footnotes class=\"footnotes\"><h2 class=\"sr-only\" id=\"footnote-label\">Footnotes</h2>\n<ol>\n<li id=\"user-content-pl-2024-06-jak-wrocic-z-amsterdamu-fn-1\">\n<p>Umykały mi te połączenia z powodu że nie startują z Amsterdam Centraal, tylko jakiegoś innego połączenia. <a href=\"#user-content-pl-2024-06-jak-wrocic-z-amsterdamu-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-pl-2024-06-jak-wrocic-z-amsterdamu-fn-2\">\n<p>Też jestem pod wrażeniem jakie niesamowite zniżki mi wchodzą, ale to w większości efekt kupowania porannego biletu z ogromnym wyprzedzeniem chyba. <a href=\"#user-content-pl-2024-06-jak-wrocic-z-amsterdamu-fnref-2\" data-footnote-backref=\"\" aria-label=\"Back to reference 2\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-pl-2024-06-jak-wrocic-z-amsterdamu-fn-3\">\n<p>Który i tak mam wrażenie że wziąłem na siłę na te kilka dni. <a href=\"#user-content-pl-2024-06-jak-wrocic-z-amsterdamu-fnref-3\" data-footnote-backref=\"\" aria-label=\"Back to reference 3\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-pl-2024-06-jak-wrocic-z-amsterdamu-fn-4\">\n<p>#ADHD thing, aby wciąż do przodu i wciąż doświadczań nowych bodżców. <a href=\"#user-content-pl-2024-06-jak-wrocic-z-amsterdamu-fnref-4\" data-footnote-backref=\"\" aria-label=\"Back to reference 4\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",[],"en/2026/04/rust-docker-cache",{id:268,data:270,body:286,filePath:287,digest:288,rendered:289},{title:271,date:272,tags:273,translationKey:281,relations:282,draft:51},"Rust, Docker, and the GHA layer caching problem",["Date","2026-04-27T16:30:02.000Z"],[274,275,276,277,278,279,280],"Rust","Docker","DevOps","Vibecoding","GitHub Actions","Projekty/Kartoteka","Sideprojects","rust-docker-cache-2026-04",[283],{type:284,post:285},"related",{id:117,collection:9},"Lately I've been working on my own vibe-designed todo app rewrite in Rust[^1]. Along the way I started looking for a sensible path to optimizing Docker image builds on GitHub Actions.\n\nOne of the solutions you can easily stumble upon is [`cargo-chef`](https://github.com/lukemathwalker/cargo-chef) — it separates dependency fetching from building the actual code to better cache layers. The problem is it's designed for simpler applications with a single `lib.rs`. In a workspace with more crates it doesn't cache what it should, and every push ends up recompiling everything from scratch.\n\nTwo approaches I tried: buildkit cache dance[^2] — speeds things up a bit, but doesn't cache brilliantly and adds its own time overhead[^3] — and [`swatinem/rust-cache`](https://github.com/swatinem/rust-cache), which works nicely on GHA for binary caching, but deploying Kartoteka as a Docker image on Coolify rules that action out.\n\nResearch turned up `sccache` as worth trying — I made an attempt, but Hetzner S3 is a no-go[^4]. So Cloudflare R2 on the free tier as a potential alternative[^5].\n\nFor now I'm parking at cache dance. Not ruling out going toward my own runner with local cache — just on a slightly bigger server.\n\n[^1]: Kartoteka — somewhere between Todoist, Jira, Amazing Marvin, and Toggl. Classic scope creep.\n[^2]: [Example in the Kartoteka repo.](https://github.com/jpalczewski/kartoteka/blob/a588f99a204ec6c3688f2ae7aafe9ab8cd883559/.github/workflows/docker-build.yml)\n[^3]: In Kartoteka's case there's also the exotic stack — Leptos — which means deploying the server binary together with the built frontend/wasm.\n[^4]: Hetzner S3 bills storage in 1 TB blocks. A bit astronomical for one innocent backup and build artifacts.\n[^5]: Yes, I know — suggesting I go back to Cloudflare when I've spent two weeks rewriting an MCP from a Cloudflare Worker to axum/rmcp specifically to get off the Cloudflare ecosystem, sure.","src/content/thoughts/en/2026/04/rust-docker-cache.md","294e7cb0a496037c",{html:290,metadata:291},"<p>Lately I’ve been working on my own vibe-designed todo app rewrite in Rust<sup><a href=\"#user-content-fn-1\" id=\"user-content-fnref-1\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">1</a></sup>. Along the way I started looking for a sensible path to optimizing Docker image builds on GitHub Actions.</p>\n<p>One of the solutions you can easily stumble upon is <a href=\"https://github.com/lukemathwalker/cargo-chef\"><code>cargo-chef</code></a> — it separates dependency fetching from building the actual code to better cache layers. The problem is it’s designed for simpler applications with a single <code>lib.rs</code>. In a workspace with more crates it doesn’t cache what it should, and every push ends up recompiling everything from scratch.</p>\n<p>Two approaches I tried: buildkit cache dance<sup><a href=\"#user-content-fn-2\" id=\"user-content-fnref-2\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">2</a></sup> — speeds things up a bit, but doesn’t cache brilliantly and adds its own time overhead<sup><a href=\"#user-content-fn-3\" id=\"user-content-fnref-3\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">3</a></sup> — and <a href=\"https://github.com/swatinem/rust-cache\"><code>swatinem/rust-cache</code></a>, which works nicely on GHA for binary caching, but deploying Kartoteka as a Docker image on Coolify rules that action out.</p>\n<p>Research turned up <code>sccache</code> as worth trying — I made an attempt, but Hetzner S3 is a no-go<sup><a href=\"#user-content-fn-4\" id=\"user-content-fnref-4\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">4</a></sup>. So Cloudflare R2 on the free tier as a potential alternative<sup><a href=\"#user-content-fn-5\" id=\"user-content-fnref-5\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">5</a></sup>.</p>\n<p>For now I’m parking at cache dance. Not ruling out going toward my own runner with local cache — just on a slightly bigger server.</p>\n<section data-footnotes=\"\" class=\"footnotes\"><h2 class=\"\" id=\"footnote-label\">Footnotes</h2>\n<ol>\n<li id=\"user-content-fn-1\">\n<p>Kartoteka — somewhere between Todoist, Jira, Amazing Marvin, and Toggl. Classic scope creep. <a href=\"#user-content-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-fn-2\">\n<p><a href=\"https://github.com/jpalczewski/kartoteka/blob/a588f99a204ec6c3688f2ae7aafe9ab8cd883559/.github/workflows/docker-build.yml\">Example in the Kartoteka repo.</a> <a href=\"#user-content-fnref-2\" data-footnote-backref=\"\" aria-label=\"Back to reference 2\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-fn-3\">\n<p>In Kartoteka’s case there’s also the exotic stack — Leptos — which means deploying the server binary together with the built frontend/wasm. <a href=\"#user-content-fnref-3\" data-footnote-backref=\"\" aria-label=\"Back to reference 3\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-fn-4\">\n<p>Hetzner S3 bills storage in 1 TB blocks. A bit astronomical for one innocent backup and build artifacts. <a href=\"#user-content-fnref-4\" data-footnote-backref=\"\" aria-label=\"Back to reference 4\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-fn-5\">\n<p>Yes, I know — suggesting I go back to Cloudflare when I’ve spent two weeks rewriting an MCP from a Cloudflare Worker to axum/rmcp specifically to get off the Cloudflare ecosystem, sure. <a href=\"#user-content-fnref-5\" data-footnote-backref=\"\" aria-label=\"Back to reference 5\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",{headings:292,localImagePaths:294,remoteImagePaths:295,frontmatter:296,imagePaths:302},[293],{depth:28,slug:29,text:30},[],[],{title:271,date:297,tags:298,draft:51,lang:37,translationKey:281,relations:299,previewHtml:301},["Date","2026-04-27T16:30:02.000Z"],[274,275,276,277,278,279,280],[300],{type:284,post:117},"<p>Lately I’ve been working on my own vibe-designed todo app rewrite in Rust<sup><a href=\"#user-content-en-2026-04-rust-docker-cache-fn-1\" id=\"user-content-en-2026-04-rust-docker-cache-fnref-1\" data-footnote-ref aria-describedby=\"footnote-label\">1</a></sup>. Along the way I started looking for a sensible path to optimizing Docker image builds on GitHub Actions.</p>\n<p>One of the solutions you can easily stumble upon is <a href=\"https://github.com/lukemathwalker/cargo-chef\"><code>cargo-chef</code></a> — it separates dependency fetching from building the actual code to better cache layers. The problem is it’s designed for simpler applications with a single <code>lib.rs</code>. In a workspace with more crates it doesn’t cache what it should, and every push ends up recompiling everything from scratch.</p>\n<p>Two approaches I tried: buildkit cache dance<sup><a href=\"#user-content-en-2026-04-rust-docker-cache-fn-2\" id=\"user-content-en-2026-04-rust-docker-cache-fnref-2\" data-footnote-ref aria-describedby=\"footnote-label\">2</a></sup> — speeds things up a bit, but doesn’t cache brilliantly and adds its own time overhead<sup><a href=\"#user-content-en-2026-04-rust-docker-cache-fn-3\" id=\"user-content-en-2026-04-rust-docker-cache-fnref-3\" data-footnote-ref aria-describedby=\"footnote-label\">3</a></sup> — and <a href=\"https://github.com/swatinem/rust-cache\"><code>swatinem/rust-cache</code></a>, which works nicely on GHA for binary caching, but deploying Kartoteka as a Docker image on Coolify rules that action out.</p>\n<p>Research turned up <code>sccache</code> as worth trying — I made an attempt, but Hetzner S3 is a no-go<sup><a href=\"#user-content-en-2026-04-rust-docker-cache-fn-4\" id=\"user-content-en-2026-04-rust-docker-cache-fnref-4\" data-footnote-ref aria-describedby=\"footnote-label\">4</a></sup>. So Cloudflare R2 on the free tier as a potential alternative<sup><a href=\"#user-content-en-2026-04-rust-docker-cache-fn-5\" id=\"user-content-en-2026-04-rust-docker-cache-fnref-5\" data-footnote-ref aria-describedby=\"footnote-label\">5</a></sup>.</p>\n<p>For now I’m parking at cache dance. Not ruling out going toward my own runner with local cache — just on a slightly bigger server.</p>\n<section data-footnotes class=\"footnotes\"><h2 class=\"sr-only\" id=\"footnote-label\">Footnotes</h2>\n<ol>\n<li id=\"user-content-en-2026-04-rust-docker-cache-fn-1\">\n<p>Kartoteka — somewhere between Todoist, Jira, Amazing Marvin, and Toggl. Classic scope creep. <a href=\"#user-content-en-2026-04-rust-docker-cache-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-en-2026-04-rust-docker-cache-fn-2\">\n<p><a href=\"https://github.com/jpalczewski/kartoteka/blob/a588f99a204ec6c3688f2ae7aafe9ab8cd883559/.github/workflows/docker-build.yml\">Example in the Kartoteka repo.</a> <a href=\"#user-content-en-2026-04-rust-docker-cache-fnref-2\" data-footnote-backref=\"\" aria-label=\"Back to reference 2\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-en-2026-04-rust-docker-cache-fn-3\">\n<p>In Kartoteka’s case there’s also the exotic stack — Leptos — which means deploying the server binary together with the built frontend/wasm. <a href=\"#user-content-en-2026-04-rust-docker-cache-fnref-3\" data-footnote-backref=\"\" aria-label=\"Back to reference 3\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-en-2026-04-rust-docker-cache-fn-4\">\n<p>Hetzner S3 bills storage in 1 TB blocks. A bit astronomical for one innocent backup and build artifacts. <a href=\"#user-content-en-2026-04-rust-docker-cache-fnref-4\" data-footnote-backref=\"\" aria-label=\"Back to reference 4\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-en-2026-04-rust-docker-cache-fn-5\">\n<p>Yes, I know — suggesting I go back to Cloudflare when I’ve spent two weeks rewriting an MCP from a Cloudflare Worker to axum/rmcp specifically to get off the Cloudflare ecosystem, sure. <a href=\"#user-content-en-2026-04-rust-docker-cache-fnref-5\" data-footnote-backref=\"\" aria-label=\"Back to reference 5\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",[],"pl/2024/06/malarstwo-a-design-thinking",{id:303,data:305,body:314,filePath:315,digest:316,rendered:317},{title:306,date:307,tags:308,draft:51,thread:313},"Co wspólnego ma malarstwo z design thinking",["Date","2024-07-27T00:00:00.000Z"],[309,310,311,312],"Design Thinking","Malarstwo","Sztuka","Wywiady","design","Jestem jeszcze w czasie gdy dość łapczywie przeglądam zdjęcia z podróży i teraz stwierdziłem że w ramach nasilenia prokrastynacji chcę zobaczyć o co chodzi z książką [*Lie like an artist*](https://www.bispublishers.com/lie-like-an-artist.html) - widziałem ją w przymuzealnych sklepikach zarazem w trzech miastach gdzie miałem okazję zajrzeć do miejsc związanych ze sztuką.\n\nAle przypadkiem trafiłem na artykuł o tym [samym tytule](https://www.roxinekee.com/blog/lie-like-an-artist)\nz którego jeden cytat przykuł moją szczególną uwagę:\n\n> According to our tour guide, McArdle did painstaking truth-finding to produce these two paintings. He conducted countless interviews with veterans, pored through maps and sketches, probably went to these places himself.\n\nMam dość luźne skojarzenie z tym jak Design thinking wygląda obecnie, gdzie wywiady pełnią tę istotną rolę czerpania informacji i tworzenia jeszcze lepszego doświadczenia użytkownika.","src/content/thoughts/pl/2024/06/malarstwo-a-design-thinking.md","3c5c2d0f655740c7",{html:318,metadata:319},"<p>Jestem jeszcze w czasie gdy dość łapczywie przeglądam zdjęcia z podróży i teraz stwierdziłem że w ramach nasilenia prokrastynacji chcę zobaczyć o co chodzi z książką <a href=\"https://www.bispublishers.com/lie-like-an-artist.html\"><em>Lie like an artist</em></a> - widziałem ją w przymuzealnych sklepikach zarazem w trzech miastach gdzie miałem okazję zajrzeć do miejsc związanych ze sztuką.</p>\n<p>Ale przypadkiem trafiłem na artykuł o tym <a href=\"https://www.roxinekee.com/blog/lie-like-an-artist\">samym tytule</a>\nz którego jeden cytat przykuł moją szczególną uwagę:</p>\n<blockquote>\n<p>According to our tour guide, McArdle did painstaking truth-finding to produce these two paintings. He conducted countless interviews with veterans, pored through maps and sketches, probably went to these places himself.</p>\n</blockquote>\n<p>Mam dość luźne skojarzenie z tym jak Design thinking wygląda obecnie, gdzie wywiady pełnią tę istotną rolę czerpania informacji i tworzenia jeszcze lepszego doświadczenia użytkownika.</p>",{headings:320,localImagePaths:321,remoteImagePaths:322,frontmatter:323,imagePaths:326},[],[],[],{title:306,thread:313,draft:51,tags:324,date:325,previewHtml:318},[309,310,311,312],["Date","2024-07-27T00:00:00.000Z"],[],"pl/2024/06/udar-a-alkohol",{id:327,data:329,body:337,filePath:338,digest:339,rendered:340},{title:330,date:331,tags:332,draft:51,thread:336},"Udar a alkohol",["Date","2024-06-13T00:00:00.000Z"],[333,334,335],"Alkohol","Udar","Praca magisterska","health","_Żeby mieć trochę contentu, wrzucam stare podejścia do pisania_\n\n Przechodząc przez literaturę do pracy magisterskiej znalazłem jedną, nieoczywistą ciekawostkę: otóż małe[^1] spożycie alkoholu zmniejsza prawdopodobieństwo udaru krwotocznego. Na krwotoczny nie robi różnicy - natomiast picie dużo bądź w ciągach już te prawdopodobieństwo dość mocno zwiększa.\n \n> Light and moderate alcohol consumption was associated with a lower risk of ischemic stroke, whereas high and heavy drinking was associated with an increased risk;\n\n[Źródło.](https://bmcmedicine.biomedcentral.com/articles/10.1186/s12916-016-0721-4) \n\nOczywiście, to nie wyraża mojej opinii wobec alkoholu - tutaj bliżej mi do perspektywy Davida Nutta, autora m.in. [[Narkotyki bez paniki]] która określa alkohol mianem najbardziej szkodliwej używki[^2] - w analizie która nie patrzy tylko na koszty osobowo/zdrowotne, ale patrzy szerzej, uwzględniając też koszty społeczne danej związane z daną substancją.\n\n[^1]: Do 12 gram alkoholu etylowego.\n[^2]: Niestety premiera nowej książki wyparła z SEO googla stare artykuły na ten temat","src/content/thoughts/pl/2024/06/udar-a-alkohol.md","0996e8f5df01c6e8",{html:341,metadata:342},"<p><em>Żeby mieć trochę contentu, wrzucam stare podejścia do pisania</em></p>\n<p>Przechodząc przez literaturę do pracy magisterskiej znalazłem jedną, nieoczywistą ciekawostkę: otóż małe<sup><a href=\"#user-content-fn-1\" id=\"user-content-fnref-1\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">1</a></sup> spożycie alkoholu zmniejsza prawdopodobieństwo udaru krwotocznego. Na krwotoczny nie robi różnicy - natomiast picie dużo bądź w ciągach już te prawdopodobieństwo dość mocno zwiększa.</p>\n<blockquote>\n<p>Light and moderate alcohol consumption was associated with a lower risk of ischemic stroke, whereas high and heavy drinking was associated with an increased risk;</p>\n</blockquote>\n<p><a href=\"https://bmcmedicine.biomedcentral.com/articles/10.1186/s12916-016-0721-4\">Źródło.</a></p>\n<p>Oczywiście, to nie wyraża mojej opinii wobec alkoholu - tutaj bliżej mi do perspektywy Davida Nutta, autora m.in. [[Narkotyki bez paniki]] która określa alkohol mianem najbardziej szkodliwej używki<sup><a href=\"#user-content-fn-2\" id=\"user-content-fnref-2\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">2</a></sup> - w analizie która nie patrzy tylko na koszty osobowo/zdrowotne, ale patrzy szerzej, uwzględniając też koszty społeczne danej związane z daną substancją.</p>\n<section data-footnotes=\"\" class=\"footnotes\"><h2 class=\"\" id=\"footnote-label\">Przypisy</h2>\n<ol>\n<li id=\"user-content-fn-1\">\n<p>Do 12 gram alkoholu etylowego. <a href=\"#user-content-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-fn-2\">\n<p>Niestety premiera nowej książki wyparła z SEO googla stare artykuły na ten temat <a href=\"#user-content-fnref-2\" data-footnote-backref=\"\" aria-label=\"Back to reference 2\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",{headings:343,localImagePaths:345,remoteImagePaths:346,frontmatter:347,imagePaths:351},[344],{depth:28,slug:29,text:160},[],[],{title:330,thread:336,draft:51,tags:348,date:349,previewHtml:350},[333,334,335],["Date","2024-06-13T00:00:00.000Z"],"<p><em>Żeby mieć trochę contentu, wrzucam stare podejścia do pisania</em></p>\n<p>Przechodząc przez literaturę do pracy magisterskiej znalazłem jedną, nieoczywistą ciekawostkę: otóż małe<sup><a href=\"#user-content-pl-2024-06-udar-a-alkohol-fn-1\" id=\"user-content-pl-2024-06-udar-a-alkohol-fnref-1\" data-footnote-ref aria-describedby=\"footnote-label\">1</a></sup> spożycie alkoholu zmniejsza prawdopodobieństwo udaru krwotocznego. Na krwotoczny nie robi różnicy - natomiast picie dużo bądź w ciągach już te prawdopodobieństwo dość mocno zwiększa.</p>\n<blockquote>\n<p>Light and moderate alcohol consumption was associated with a lower risk of ischemic stroke, whereas high and heavy drinking was associated with an increased risk;</p>\n</blockquote>\n<p><a href=\"https://bmcmedicine.biomedcentral.com/articles/10.1186/s12916-016-0721-4\">Źródło.</a></p>\n<p>Oczywiście, to nie wyraża mojej opinii wobec alkoholu - tutaj bliżej mi do perspektywy Davida Nutta, autora m.in. [[Narkotyki bez paniki]] która określa alkohol mianem najbardziej szkodliwej używki<sup><a href=\"#user-content-pl-2024-06-udar-a-alkohol-fn-2\" id=\"user-content-pl-2024-06-udar-a-alkohol-fnref-2\" data-footnote-ref aria-describedby=\"footnote-label\">2</a></sup> - w analizie która nie patrzy tylko na koszty osobowo/zdrowotne, ale patrzy szerzej, uwzględniając też koszty społeczne danej związane z daną substancją.</p>\n<section data-footnotes class=\"footnotes\"><h2 class=\"sr-only\" id=\"footnote-label\">Footnotes</h2>\n<ol>\n<li id=\"user-content-pl-2024-06-udar-a-alkohol-fn-1\">\n<p>Do 12 gram alkoholu etylowego. <a href=\"#user-content-pl-2024-06-udar-a-alkohol-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-pl-2024-06-udar-a-alkohol-fn-2\">\n<p>Niestety premiera nowej książki wyparła z SEO googla stare artykuły na ten temat <a href=\"#user-content-pl-2024-06-udar-a-alkohol-fnref-2\" data-footnote-backref=\"\" aria-label=\"Back to reference 2\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",[],"pl/2025/11/hello-world",{id:352,data:354,body:361,filePath:362,digest:363,rendered:364},{title:355,date:356,tags:357,translationKey:360,draft:51},"Hello, world",["Date","2025-11-12T00:00:00.000Z"],[358,359],"Tech/astro","Personal/projects","astro-blog-setup-nov-2025","Kolejne, finalne podejście do blogowania.  Styl jest od początku do końca zrobiony za pomocą vibecodingu - w duźej mierze to efekt darmowych tokenów na claude code web i zapału do skomplikowanych inicjatyw.\n\nA zapytacie[^1], dlaczego wracam nieustannie na github pages? To ma nieodmienny związek z...lękiem przed śmiercią. Jest w tym coś minimalnie kojącego, że jak kiedyś mnie zabraknie, to te miejsce bdzie trwało trochę dłużej. A infekowanie własną twórczością datasetów kolejnych modeli AI...czy to te słynne życie wieczne?\n\n[^1]: jasne, mogę wejść sobie w dialog z czytelnikiem, ale wątpię, że ktokolwiek to przeczyta.","src/content/thoughts/pl/2025/11/hello-world.md","f945db62b3981264",{html:365,metadata:366},"<p>Kolejne, finalne podejście do blogowania.  Styl jest od początku do końca zrobiony za pomocą vibecodingu - w duźej mierze to efekt darmowych tokenów na claude code web i zapału do skomplikowanych inicjatyw.</p>\n<p>A zapytacie<sup><a href=\"#user-content-fn-1\" id=\"user-content-fnref-1\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">1</a></sup>, dlaczego wracam nieustannie na github pages? To ma nieodmienny związek z…lękiem przed śmiercią. Jest w tym coś minimalnie kojącego, że jak kiedyś mnie zabraknie, to te miejsce bdzie trwało trochę dłużej. A infekowanie własną twórczością datasetów kolejnych modeli AI…czy to te słynne życie wieczne?</p>\n<section data-footnotes=\"\" class=\"footnotes\"><h2 class=\"\" id=\"footnote-label\">Przypisy</h2>\n<ol>\n<li id=\"user-content-fn-1\">\n<p>jasne, mogę wejść sobie w dialog z czytelnikiem, ale wątpię, że ktokolwiek to przeczyta. <a href=\"#user-content-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",{headings:367,localImagePaths:369,remoteImagePaths:370,frontmatter:371,imagePaths:375},[368],{depth:28,slug:29,text:160},[],[],{title:355,date:372,tags:373,translationKey:360,draft:51,previewHtml:374},["Date","2025-11-12T00:00:00.000Z"],[358,359],"<p>Kolejne, finalne podejście do blogowania.  Styl jest od początku do końca zrobiony za pomocą vibecodingu - w duźej mierze to efekt darmowych tokenów na claude code web i zapału do skomplikowanych inicjatyw.</p>\n<p>A zapytacie<sup><a href=\"#user-content-pl-2025-11-hello-world-fn-1\" id=\"user-content-pl-2025-11-hello-world-fnref-1\" data-footnote-ref aria-describedby=\"footnote-label\">1</a></sup>, dlaczego wracam nieustannie na github pages? To ma nieodmienny związek z…lękiem przed śmiercią. Jest w tym coś minimalnie kojącego, że jak kiedyś mnie zabraknie, to te miejsce bdzie trwało trochę dłużej. A infekowanie własną twórczością datasetów kolejnych modeli AI…czy to te słynne życie wieczne?</p>\n<section data-footnotes class=\"footnotes\"><h2 class=\"sr-only\" id=\"footnote-label\">Footnotes</h2>\n<ol>\n<li id=\"user-content-pl-2025-11-hello-world-fn-1\">\n<p>jasne, mogę wejść sobie w dialog z czytelnikiem, ale wątpię, że ktokolwiek to przeczyta. <a href=\"#user-content-pl-2025-11-hello-world-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",[],"pl/2025/11/a-jak-wyglada-droga-do-budapesztu",{id:376,data:378,body:385,filePath:386,digest:387,rendered:388},{title:379,date:380,tags:381,relations:382,draft:51},"A jak wygląda droga do Budapesztu?",["Date","2025-11-13T23:08:48.104Z"],[203,204],[383],{type:284,post:384},{id:197,collection:9},"Wrzucając stare posty żeby jakkolwiek zapełnić nowego bloga treścią, Fajnie będzie dodać do do moich rozkmin na temat Amsterdamu, jak wygląda kwestia Budapesztu pod kątem cen transportu. Long story short:  we wrześniu był tam Lil Texas, więc stwierdziłem ze muszę tam być!\n\nW porównaniu do horrendalnych cen transportu do Europy Zachodniej, za nocny do Budapesztu zapłaciłem około 200 zł - więcej mnie wyniósł powrotny, ponieważ przez moje niedopatrzenie dostałem pierwszą klasę kupując bilet w kasie[^1].\n\nPrzy okazji ciekawostka podróżnicza: Gdyby ktoś kiedyś polując na super promu miał problem z powrotem z Budapestu to można rozkminić przysiadkę w ramach jednej relacji: nie miałem powrotnych do Warszawy, ale były miejsca do Katowic – więc kupując w relacji krajowej od Katowic do Warszawy można dojechać mimo braku biletów.[^2]\n\n[^1]: Zapytacie dlaczego? Wierzyłem ze na jednym bilecie dostanę relację Olsztyn-Budapeszt - niestety, międzynarodowe są na innym druku i chyba nie jest możliwa taka sprzedaż. Chociaż przerażenie w oczach kasjerki sprzedającej bilety na relacje międzynarodowe jest bezcenne - system jest tak cholernie nieintuicyjny z tego co obserwuję z boku.\n\n[^2]: Jednego razu bardzo zależało mi na powrocie z Katowic i miejscu siedzącym - Udało mi się rozbić Jeden bilet na trzy przesiadki w ramach tej samej relacji xD","src/content/thoughts/pl/2025/11/a-jak-wyglada-droga-do-budapesztu.md","0b2d4e9fe0ad29a3",{html:389,metadata:390},"<p>Wrzucając stare posty żeby jakkolwiek zapełnić nowego bloga treścią, Fajnie będzie dodać do do moich rozkmin na temat Amsterdamu, jak wygląda kwestia Budapesztu pod kątem cen transportu. Long story short:  we wrześniu był tam Lil Texas, więc stwierdziłem ze muszę tam być!</p>\n<p>W porównaniu do horrendalnych cen transportu do Europy Zachodniej, za nocny do Budapesztu zapłaciłem około 200 zł - więcej mnie wyniósł powrotny, ponieważ przez moje niedopatrzenie dostałem pierwszą klasę kupując bilet w kasie<sup><a href=\"#user-content-fn-1\" id=\"user-content-fnref-1\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">1</a></sup>.</p>\n<p>Przy okazji ciekawostka podróżnicza: Gdyby ktoś kiedyś polując na super promu miał problem z powrotem z Budapestu to można rozkminić przysiadkę w ramach jednej relacji: nie miałem powrotnych do Warszawy, ale były miejsca do Katowic – więc kupując w relacji krajowej od Katowic do Warszawy można dojechać mimo braku biletów.<sup><a href=\"#user-content-fn-2\" id=\"user-content-fnref-2\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">2</a></sup></p>\n<section data-footnotes=\"\" class=\"footnotes\"><h2 class=\"\" id=\"footnote-label\">Przypisy</h2>\n<ol>\n<li id=\"user-content-fn-1\">\n<p>Zapytacie dlaczego? Wierzyłem ze na jednym bilecie dostanę relację Olsztyn-Budapeszt - niestety, międzynarodowe są na innym druku i chyba nie jest możliwa taka sprzedaż. Chociaż przerażenie w oczach kasjerki sprzedającej bilety na relacje międzynarodowe jest bezcenne - system jest tak cholernie nieintuicyjny z tego co obserwuję z boku. <a href=\"#user-content-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-fn-2\">\n<p>Jednego razu bardzo zależało mi na powrocie z Katowic i miejscu siedzącym - Udało mi się rozbić Jeden bilet na trzy przesiadki w ramach tej samej relacji xD <a href=\"#user-content-fnref-2\" data-footnote-backref=\"\" aria-label=\"Back to reference 2\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",{headings:391,localImagePaths:393,remoteImagePaths:394,frontmatter:395,imagePaths:402},[392],{depth:28,slug:29,text:160},[],[],{title:379,description:396,date:397,tags:398,draft:51,lang:166,relations:399,previewHtml:401},"A new post about pociągi, podróże",["Date","2025-11-13T23:08:48.104Z"],[203,204],[400],{type:284,post:197},"<p>Wrzucając stare posty żeby jakkolwiek zapełnić nowego bloga treścią, Fajnie będzie dodać do do moich rozkmin na temat Amsterdamu, jak wygląda kwestia Budapesztu pod kątem cen transportu. Long story short:  we wrześniu był tam Lil Texas, więc stwierdziłem ze muszę tam być!</p>\n<p>W porównaniu do horrendalnych cen transportu do Europy Zachodniej, za nocny do Budapesztu zapłaciłem około 200 zł - więcej mnie wyniósł powrotny, ponieważ przez moje niedopatrzenie dostałem pierwszą klasę kupując bilet w kasie<sup><a href=\"#user-content-pl-2025-11-a-jak-wyglada-droga-do-budapesztu-fn-1\" id=\"user-content-pl-2025-11-a-jak-wyglada-droga-do-budapesztu-fnref-1\" data-footnote-ref aria-describedby=\"footnote-label\">1</a></sup>.</p>\n<p>Przy okazji ciekawostka podróżnicza: Gdyby ktoś kiedyś polując na super promu miał problem z powrotem z Budapestu to można rozkminić przysiadkę w ramach jednej relacji: nie miałem powrotnych do Warszawy, ale były miejsca do Katowic – więc kupując w relacji krajowej od Katowic do Warszawy można dojechać mimo braku biletów.<sup><a href=\"#user-content-pl-2025-11-a-jak-wyglada-droga-do-budapesztu-fn-2\" id=\"user-content-pl-2025-11-a-jak-wyglada-droga-do-budapesztu-fnref-2\" data-footnote-ref aria-describedby=\"footnote-label\">2</a></sup></p>\n<section data-footnotes class=\"footnotes\"><h2 class=\"sr-only\" id=\"footnote-label\">Footnotes</h2>\n<ol>\n<li id=\"user-content-pl-2025-11-a-jak-wyglada-droga-do-budapesztu-fn-1\">\n<p>Zapytacie dlaczego? Wierzyłem ze na jednym bilecie dostanę relację Olsztyn-Budapeszt - niestety, międzynarodowe są na innym druku i chyba nie jest możliwa taka sprzedaż. Chociaż przerażenie w oczach kasjerki sprzedającej bilety na relacje międzynarodowe jest bezcenne - system jest tak cholernie nieintuicyjny z tego co obserwuję z boku. <a href=\"#user-content-pl-2025-11-a-jak-wyglada-droga-do-budapesztu-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-pl-2025-11-a-jak-wyglada-droga-do-budapesztu-fn-2\">\n<p>Jednego razu bardzo zależało mi na powrocie z Katowic i miejscu siedzącym - Udało mi się rozbić Jeden bilet na trzy przesiadki w ramach tej samej relacji xD <a href=\"#user-content-pl-2025-11-a-jak-wyglada-droga-do-budapesztu-fnref-2\" data-footnote-backref=\"\" aria-label=\"Back to reference 2\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",[],"pl/2026/04/aaaaa-rejwa-szukam",{id:403,data:405,body:412,filePath:413,digest:414,deferredRender:19},{title:406,date:407,tags:408,tldr:411,draft:51},"AAAAA Rejwa szukam",["Date","2026-04-27T00:00:00.000Z"],[409,410],"Rave","Podróśe","Europejsko-polski spis imprez.","import { YouTube } from 'astro-embed';\n\n\nJednym z najbardziej niespecyficznych nawyków które mam, to obczajanie zagranicznych miast na Resident Advisor:\n\n![Resident Advisor](@assets/images/resident-advisor.png \"pov: moje typowa historia przeglądania gdy myślę o wyjeździe za granicę\")\n\nZaczęło się rok temu jak przypadkiem trafiłem na Lil Texasa w Budapeszcie.\n\n<figure class=\"post-figure\">\n  <YouTube id=\"SWDZJDfiFJw\" />\n  <figcaption>Domyślam się ze nie kady zna, dlatego tez podrzucam przykład xD</figcaption>\n</figure>\n\nDo refleksji i wspomnień pewnie jeszcze wrócę, ale gdyby  ktoś szukał inspiracji jak na imprezę za granicę  bądź w Polsce trafić, to  chciałbym popełnić spis  stron na które warto rzucić okiem planując jakiś wyjazd.\n\n## Polska\n\n- [Załoga Rave](https://zalogarave.pl/) jest całkiem  przyjemnym agregatorem imprez - nie spaczonym gatunkowo, co mozemy postrzegac zarowno w formie zalety jak i wady \n- [Core'owe Ogłoszenia Parafialne](https://www.facebook.com/CoreInfoPL?locale=pl_PL) tu juz stricte hardkory i inne gatunki muzyczne\n\n## Holandia\n\n- [Partyflock](https://partyflock.nl/) - na chwilę pisania posta niestety nie działa, ale gdyby miała wrócić - polecam!\n\n\n## Ogólne\n\n- [Resident Advisor](https://pl.ra.co/) - na plus bardzo duza baza z rozbiciem na gatunki, na minus - w wiekszych krajach brak mi feedów narodowych[^1]\n- [Harderstylemap](https://harderstylemap.com/) - niczym core'owe ogłoszenia parafialne, ino z mapą. I bez barier.\n\n[^1]: Mam tak na przykład z Wielką Brytanią lub Francją","src/content/thoughts/pl/2026/04/aaaaa-rejwa-szukam.mdx","38d7c35c312eeec7","pl/2026/04/rust-docker-cache",{id:415,data:417,body:423,filePath:424,digest:425,rendered:426},{title:418,date:419,tags:420,translationKey:281,draft:51,thread:422},"Rust, Docker i problem z cache'owaniem warstw na GHA",["Date","2026-04-26T00:00:00.000Z"],[274,275,276,277,278,279,421],"Sideprojekty","tech","Ostatnio dłubię sobie własny vibe-designed rewrite aplikacji todo w Ruscie[^1]. Przy okazji zacząłem szukać sensownej ścieżki do optymalizowania budowania obrazów Dockerowych na GitHub Actions.\n\nJedno z rozwiązań, na które można dość łatwo trafić, to [`cargo-chef`](https://github.com/lukemathwalker/cargo-chef) — separuje pobieranie zależności od właściwego kodu, żeby lepiej cache'ować warstwy. Problem w tym, że jest projektowany pod prostsze aplikacje z jednym `lib.rs`. W workspace z większą liczbą crate'ów nie cache'uje tego co trzeba i przy każdym pushu i tak kompilujesz wszystko od nowa.\n\nDwa podejścia które próbowałem: buildkit cache dance[^2] — trochę przyspiesza, ale nie cache'uje rewelacyjnie i dorzuca własny narzut czasowy[^3] — oraz [`swatinem/rust-cache`](https://github.com/swatinem/rust-cache), który na GHA sprawdza się fajnie przy cache'owaniu binarek, ale deployment Kartoteki jako obrazu Dockerowego na Coolify tę akcję wyklucza.\n\nZ researchu wyszło mi, że warto sprawdzić `sccache` — zrobiłem podejście, ale Hetzner S3 odpada[^4]. Stąd Cloudflare R2 w free tierze jako potencjalna alternatywa[^5].\n\nNa razie tymczasowo parkuję przy cache dance. Nie jest wykluczone, że pójdę w stronę własnego runnera z lokalnym cache — tylko na trochę większym serwerze.\n\n[^1]: Kartoteka — gdzieś pomiędzy Todoistem, Jirą, Amazing Marvin i Togglem. Klasyczny scope creep.\n[^2]: [Przykład w repo Kartoteka.](https://github.com/jpalczewski/kartoteka/blob/a588f99a204ec6c3688f2ae7aafe9ab8cd883559/.github/workflows/docker-build.yml)\n[^3]: W przypadku Kartoteki dochodzi jeszcze kwestia egzotycznego stacku w postaci Leptosa — razem z plikiem serwera trzeba też deployować zbudowany frontend/wasm.\n[^4]: Hetzner S3 rozlicza storage w pakietach po 1 TB — jak na jeden niewinny backup i artefakty do cache to trochę astronomiczne.\n[^5]: Tak, wiem — sugerowanie żebym wracał do Cloudflare, kiedy od dwóch tygodni przepisuję MCP z Cloudflare Workera na axum/rmcp żeby zejść z ekosystemu Cloudflare, mhm.","src/content/thoughts/pl/2026/04/rust-docker-cache.md","801aa9b34226e197",{html:427,metadata:428},"<p>Ostatnio dłubię sobie własny vibe-designed rewrite aplikacji todo w Ruscie<sup><a href=\"#user-content-fn-1\" id=\"user-content-fnref-1\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">1</a></sup>. Przy okazji zacząłem szukać sensownej ścieżki do optymalizowania budowania obrazów Dockerowych na GitHub Actions.</p>\n<p>Jedno z rozwiązań, na które można dość łatwo trafić, to <a href=\"https://github.com/lukemathwalker/cargo-chef\"><code>cargo-chef</code></a> — separuje pobieranie zależności od właściwego kodu, żeby lepiej cache’ować warstwy. Problem w tym, że jest projektowany pod prostsze aplikacje z jednym <code>lib.rs</code>. W workspace z większą liczbą crate’ów nie cache’uje tego co trzeba i przy każdym pushu i tak kompilujesz wszystko od nowa.</p>\n<p>Dwa podejścia które próbowałem: buildkit cache dance<sup><a href=\"#user-content-fn-2\" id=\"user-content-fnref-2\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">2</a></sup> — trochę przyspiesza, ale nie cache’uje rewelacyjnie i dorzuca własny narzut czasowy<sup><a href=\"#user-content-fn-3\" id=\"user-content-fnref-3\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">3</a></sup> — oraz <a href=\"https://github.com/swatinem/rust-cache\"><code>swatinem/rust-cache</code></a>, który na GHA sprawdza się fajnie przy cache’owaniu binarek, ale deployment Kartoteki jako obrazu Dockerowego na Coolify tę akcję wyklucza.</p>\n<p>Z researchu wyszło mi, że warto sprawdzić <code>sccache</code> — zrobiłem podejście, ale Hetzner S3 odpada<sup><a href=\"#user-content-fn-4\" id=\"user-content-fnref-4\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">4</a></sup>. Stąd Cloudflare R2 w free tierze jako potencjalna alternatywa<sup><a href=\"#user-content-fn-5\" id=\"user-content-fnref-5\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">5</a></sup>.</p>\n<p>Na razie tymczasowo parkuję przy cache dance. Nie jest wykluczone, że pójdę w stronę własnego runnera z lokalnym cache — tylko na trochę większym serwerze.</p>\n<section data-footnotes=\"\" class=\"footnotes\"><h2 class=\"\" id=\"footnote-label\">Przypisy</h2>\n<ol>\n<li id=\"user-content-fn-1\">\n<p>Kartoteka — gdzieś pomiędzy Todoistem, Jirą, Amazing Marvin i Togglem. Klasyczny scope creep. <a href=\"#user-content-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-fn-2\">\n<p><a href=\"https://github.com/jpalczewski/kartoteka/blob/a588f99a204ec6c3688f2ae7aafe9ab8cd883559/.github/workflows/docker-build.yml\">Przykład w repo Kartoteka.</a> <a href=\"#user-content-fnref-2\" data-footnote-backref=\"\" aria-label=\"Back to reference 2\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-fn-3\">\n<p>W przypadku Kartoteki dochodzi jeszcze kwestia egzotycznego stacku w postaci Leptosa — razem z plikiem serwera trzeba też deployować zbudowany frontend/wasm. <a href=\"#user-content-fnref-3\" data-footnote-backref=\"\" aria-label=\"Back to reference 3\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-fn-4\">\n<p>Hetzner S3 rozlicza storage w pakietach po 1 TB — jak na jeden niewinny backup i artefakty do cache to trochę astronomiczne. <a href=\"#user-content-fnref-4\" data-footnote-backref=\"\" aria-label=\"Back to reference 4\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-fn-5\">\n<p>Tak, wiem — sugerowanie żebym wracał do Cloudflare, kiedy od dwóch tygodni przepisuję MCP z Cloudflare Workera na axum/rmcp żeby zejść z ekosystemu Cloudflare, mhm. <a href=\"#user-content-fnref-5\" data-footnote-backref=\"\" aria-label=\"Back to reference 5\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",{headings:429,localImagePaths:431,remoteImagePaths:432,frontmatter:433,imagePaths:437},[430],{depth:28,slug:29,text:160},[],[],{title:418,date:434,tags:435,draft:51,lang:166,thread:422,translationKey:281,previewHtml:436},["Date","2026-04-26T00:00:00.000Z"],[274,275,276,277,278,279,421],"<p>Ostatnio dłubię sobie własny vibe-designed rewrite aplikacji todo w Ruscie<sup><a href=\"#user-content-pl-2026-04-rust-docker-cache-fn-1\" id=\"user-content-pl-2026-04-rust-docker-cache-fnref-1\" data-footnote-ref aria-describedby=\"footnote-label\">1</a></sup>. Przy okazji zacząłem szukać sensownej ścieżki do optymalizowania budowania obrazów Dockerowych na GitHub Actions.</p>\n<p>Jedno z rozwiązań, na które można dość łatwo trafić, to <a href=\"https://github.com/lukemathwalker/cargo-chef\"><code>cargo-chef</code></a> — separuje pobieranie zależności od właściwego kodu, żeby lepiej cache’ować warstwy. Problem w tym, że jest projektowany pod prostsze aplikacje z jednym <code>lib.rs</code>. W workspace z większą liczbą crate’ów nie cache’uje tego co trzeba i przy każdym pushu i tak kompilujesz wszystko od nowa.</p>\n<p>Dwa podejścia które próbowałem: buildkit cache dance<sup><a href=\"#user-content-pl-2026-04-rust-docker-cache-fn-2\" id=\"user-content-pl-2026-04-rust-docker-cache-fnref-2\" data-footnote-ref aria-describedby=\"footnote-label\">2</a></sup> — trochę przyspiesza, ale nie cache’uje rewelacyjnie i dorzuca własny narzut czasowy<sup><a href=\"#user-content-pl-2026-04-rust-docker-cache-fn-3\" id=\"user-content-pl-2026-04-rust-docker-cache-fnref-3\" data-footnote-ref aria-describedby=\"footnote-label\">3</a></sup> — oraz <a href=\"https://github.com/swatinem/rust-cache\"><code>swatinem/rust-cache</code></a>, który na GHA sprawdza się fajnie przy cache’owaniu binarek, ale deployment Kartoteki jako obrazu Dockerowego na Coolify tę akcję wyklucza.</p>\n<p>Z researchu wyszło mi, że warto sprawdzić <code>sccache</code> — zrobiłem podejście, ale Hetzner S3 odpada<sup><a href=\"#user-content-pl-2026-04-rust-docker-cache-fn-4\" id=\"user-content-pl-2026-04-rust-docker-cache-fnref-4\" data-footnote-ref aria-describedby=\"footnote-label\">4</a></sup>. Stąd Cloudflare R2 w free tierze jako potencjalna alternatywa<sup><a href=\"#user-content-pl-2026-04-rust-docker-cache-fn-5\" id=\"user-content-pl-2026-04-rust-docker-cache-fnref-5\" data-footnote-ref aria-describedby=\"footnote-label\">5</a></sup>.</p>\n<p>Na razie tymczasowo parkuję przy cache dance. Nie jest wykluczone, że pójdę w stronę własnego runnera z lokalnym cache — tylko na trochę większym serwerze.</p>\n<section data-footnotes class=\"footnotes\"><h2 class=\"sr-only\" id=\"footnote-label\">Footnotes</h2>\n<ol>\n<li id=\"user-content-pl-2026-04-rust-docker-cache-fn-1\">\n<p>Kartoteka — gdzieś pomiędzy Todoistem, Jirą, Amazing Marvin i Togglem. Klasyczny scope creep. <a href=\"#user-content-pl-2026-04-rust-docker-cache-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-pl-2026-04-rust-docker-cache-fn-2\">\n<p><a href=\"https://github.com/jpalczewski/kartoteka/blob/a588f99a204ec6c3688f2ae7aafe9ab8cd883559/.github/workflows/docker-build.yml\">Przykład w repo Kartoteka.</a> <a href=\"#user-content-pl-2026-04-rust-docker-cache-fnref-2\" data-footnote-backref=\"\" aria-label=\"Back to reference 2\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-pl-2026-04-rust-docker-cache-fn-3\">\n<p>W przypadku Kartoteki dochodzi jeszcze kwestia egzotycznego stacku w postaci Leptosa — razem z plikiem serwera trzeba też deployować zbudowany frontend/wasm. <a href=\"#user-content-pl-2026-04-rust-docker-cache-fnref-3\" data-footnote-backref=\"\" aria-label=\"Back to reference 3\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-pl-2026-04-rust-docker-cache-fn-4\">\n<p>Hetzner S3 rozlicza storage w pakietach po 1 TB — jak na jeden niewinny backup i artefakty do cache to trochę astronomiczne. <a href=\"#user-content-pl-2026-04-rust-docker-cache-fnref-4\" data-footnote-backref=\"\" aria-label=\"Back to reference 4\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-pl-2026-04-rust-docker-cache-fn-5\">\n<p>Tak, wiem — sugerowanie żebym wracał do Cloudflare, kiedy od dwóch tygodni przepisuję MCP z Cloudflare Workera na axum/rmcp żeby zejść z ekosystemu Cloudflare, mhm. <a href=\"#user-content-pl-2026-04-rust-docker-cache-fnref-5\" data-footnote-backref=\"\" aria-label=\"Back to reference 5\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",[],"pl/2025/11/optymalizacja-drogi-do-katowic",{id:438,data:440,body:444,filePath:445,digest:446,deferredRender:19},{title:441,date:442,tags:443,draft:51},"Optymalizacja drogi do Katowic",["Date","2025-11-15T16:07:41.236Z"],[203,204],"import { YouTube } from 'astro-embed';\n\n_Ten post jest literalnie tym filmem_\n<YouTube id=\"-cWAJR-K_Fw\" />\n\nPewnego sierpniowego dnia dostałem zaproszenie na rozmowę kwalifikacyjną do Katowic. Słysząc, że rozmowa będzie na miejscu to stwierdziłem....\n\n......dlaczego nie?[^2]\n\nW każdym razie, parę tygodni później jestem szczególnie dumny z jednego połączenia:\n - O 20 wsiadam w pociąg regionalny do Iławy z Olsztyna Głównego\n - Tam przesiadam się o 21 w TLK Karpaty Bądź Ustronie[^1] - czyli nocny do Krakowa\n - A w Krakowie EC Odra do Katowic, aby na miejscu w Katowicach być o 5 rano[^3]\n\nI pomyśleć, że dawno temu chciałem dużo jeździć nocnymi pociągami - do końca roku zapewne z 10 razy minimum zaliczę.\n\nW każdym razie interesującą socjologicznie zmianą jest przejcie w Iławie między światami. Mimo że zazwuczaj WARS nie grzeszy nowoczesnością, to można to postrzegać za przestrzeń jakkolwiek ekskluzywną  - cena dopłaty  oscyluje w cenie zwyczajnego hostelu, ale  mimo wszystko dziwnie się wychodziło z tego pociągu, z walizkami LV, do zwyczajnego regionalnego, pełnego uczniów dojeżdżających do szkoły.\n\n[^1]: Zawsze mylę te nazwy, a nie jest to jakoś szczególnie istotne\n\n[^2]: Szczerze, gdyby nie rejwy i oswojenie z pociągami to nigdy bym się na taką rozmowę nie zdecydował.\n\n[^3]: Jakby, słuchajcie tego: na dworcu w Katowicach jest całodobowy bar z pierogami...","src/content/thoughts/pl/2025/11/optymalizacja-drogi-do-katowic.mdx","8b244d7b54763069","pl/2026/05/analiza-ryzyka-na-wyjazdach",{id:447,data:449,body:455,filePath:456,digest:457,rendered:458},{title:450,date:451,tags:452,draft:19},"Analiza ryzyka na wyjazdach",["Date","2026-05-10T08:18:07.695Z"],[453,454],"Kraj/Austria","Miasto/Wiedeń","Mój ostatni, majówkowy wyjazd do Austrii miał jedno urocze zdarzenie.\n\nPewnego dnia, po  Albertinie stwierdziłem, że potrzebuję się wybrać / zobaczyć do parku miejskiego. Claude podpowiadał, \n\n> mordo, dawaj do Prater, najlepiej\n\nwięc stwierdziłem ze zaryzykuję. A na miejscu coś co było _parkiem rozrywki_  z warstwy słownego symbolu ukazało prawdziwą formę. Gigantyczną. Dawno nie byłem w czymś podobnym i...dużym?[^4]\n\nTechnicznie tego dnia byłem z plecakiem, więc szaleństwa nie wchodziły w grę, ale za dużo już jeżdżę[^1], także kolejnego dnia wróciłem tam gotowy po więcej.\n\nPatrząc na te gigantyczne kolejki z jednej strony miałem duży apetyt na przygodę, z innej strony byłem świadom swoich ograniczeń - tego że w końcu jestem osobą po udarze i decyzja o rollercoasterze może nie być najrozsądniejszą decyzją w moim życiu. W każdym razie chęć przygody wygrała i poszedłem na kolejkę _Insider_ - w dialogu wewnętrznym czułem że kolejka bez punktów odniesienia w ciemności będzie doświadczeniem bardziej  intensywnym przy mniejszej trasie i mniejszych prędkościach.\n\nI myśląc o tych wszystkich przypadkach udarów i skrzepach zatykających tętnice udałem się tam[^2] wchodząc w ciemność...\n\n\n...pierdolnąłem w lustro okularami, bo ktoś uznał za potrzebne wrzucenie labiryntu luster na sam początek trasy. Sama trasa fajna, ale najbardziej stresujący był wypadający telefon z kieszeni, co nie pozwoliło w pełni delektować się adrenaliną.\n\n\nStąd też  strasznie mnie śmieszy że obawiając się innych zagrożeń można spotkać zupełne inne[^3]. \n\n[^1]: Stąd też wiem że branie hoteli ma tą zaletę że często można zostawić bagaż - i czasami też na dłużej niż jeden dzień \n\n[^2]: Miałem raz w życiu podejście do Krav-Magi, gdzie bycie przewróconym na matę uważam za doświadczenie dość ożywcze - z samej aktywności zrezygnowałem gdzie neurolog sugerował że to może nie być najbardziej korzystne. \n\n[^3]: Którymi też się przejmowałem i obawiałem, ale terapia z waty cukrowej wyjątkowo złagodziła objawy.\n\n[^4]: Takie parki rozrywki przyjeżdżające do Olsztyna kojarzą mi się z latami 90-00, ale od tamtej pory nigdy nie spotkałem czegoś tak dużego.","src/content/thoughts/pl/2026/05/analiza-ryzyka-na-wyjazdach.md","fe875c9b34d7b866",{html:459,metadata:460},"<p>Mój ostatni, majówkowy wyjazd do Austrii miał jedno urocze zdarzenie.</p>\n<p>Pewnego dnia, po  Albertinie stwierdziłem, że potrzebuję się wybrać / zobaczyć do parku miejskiego. Claude podpowiadał,</p>\n<blockquote>\n<p>mordo, dawaj do Prater, najlepiej</p>\n</blockquote>\n<p>więc stwierdziłem ze zaryzykuję. A na miejscu coś co było <em>parkiem rozrywki</em>  z warstwy słownego symbolu ukazało prawdziwą formę. Gigantyczną. Dawno nie byłem w czymś podobnym i…dużym?<sup><a href=\"#user-content-fn-4\" id=\"user-content-fnref-4\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">1</a></sup></p>\n<p>Technicznie tego dnia byłem z plecakiem, więc szaleństwa nie wchodziły w grę, ale za dużo już jeżdżę<sup><a href=\"#user-content-fn-1\" id=\"user-content-fnref-1\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">2</a></sup>, także kolejnego dnia wróciłem tam gotowy po więcej.</p>\n<p>Patrząc na te gigantyczne kolejki z jednej strony miałem duży apetyt na przygodę, z innej strony byłem świadom swoich ograniczeń - tego że w końcu jestem osobą po udarze i decyzja o rollercoasterze może nie być najrozsądniejszą decyzją w moim życiu. W każdym razie chęć przygody wygrała i poszedłem na kolejkę <em>Insider</em> - w dialogu wewnętrznym czułem że kolejka bez punktów odniesienia w ciemności będzie doświadczeniem bardziej  intensywnym przy mniejszej trasie i mniejszych prędkościach.</p>\n<p>I myśląc o tych wszystkich przypadkach udarów i skrzepach zatykających tętnice udałem się tam<sup><a href=\"#user-content-fn-2\" id=\"user-content-fnref-2\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">3</a></sup> wchodząc w ciemność…</p>\n<p>…pierdolnąłem w lustro okularami, bo ktoś uznał za potrzebne wrzucenie labiryntu luster na sam początek trasy. Sama trasa fajna, ale najbardziej stresujący był wypadający telefon z kieszeni, co nie pozwoliło w pełni delektować się adrenaliną.</p>\n<p>Stąd też  strasznie mnie śmieszy że obawiając się innych zagrożeń można spotkać zupełne inne<sup><a href=\"#user-content-fn-3\" id=\"user-content-fnref-3\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">4</a></sup>.</p>\n<section data-footnotes=\"\" class=\"footnotes\"><h2 class=\"\" id=\"footnote-label\">Przypisy</h2>\n<ol>\n<li id=\"user-content-fn-4\">\n<p>Takie parki rozrywki przyjeżdżające do Olsztyna kojarzą mi się z latami 90-00, ale od tamtej pory nigdy nie spotkałem czegoś tak dużego. <a href=\"#user-content-fnref-4\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-fn-1\">\n<p>Stąd też wiem że branie hoteli ma tą zaletę że często można zostawić bagaż - i czasami też na dłużej niż jeden dzień <a href=\"#user-content-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 2\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-fn-2\">\n<p>Miałem raz w życiu podejście do Krav-Magi, gdzie bycie przewróconym na matę uważam za doświadczenie dość ożywcze - z samej aktywności zrezygnowałem gdzie neurolog sugerował że to może nie być najbardziej korzystne. <a href=\"#user-content-fnref-2\" data-footnote-backref=\"\" aria-label=\"Back to reference 3\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-fn-3\">\n<p>Którymi też się przejmowałem i obawiałem, ale terapia z waty cukrowej wyjątkowo złagodziła objawy. <a href=\"#user-content-fnref-3\" data-footnote-backref=\"\" aria-label=\"Back to reference 4\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",{headings:461,localImagePaths:463,remoteImagePaths:464,frontmatter:465,imagePaths:469},[462],{depth:28,slug:29,text:160},[],[],{title:450,date:466,tags:467,draft:19,lang:166,previewHtml:468},["Date","2026-05-10T08:18:07.695Z"],[453,454],"<p>Mój ostatni, majówkowy wyjazd do Austrii miał jedno urocze zdarzenie.</p>\n<p>Pewnego dnia, po  Albertinie stwierdziłem, że potrzebuję się wybrać / zobaczyć do parku miejskiego. Claude podpowiadał,</p>\n<blockquote>\n<p>mordo, dawaj do Prater, najlepiej</p>\n</blockquote>\n<p>więc stwierdziłem ze zaryzykuję. A na miejscu coś co było <em>parkiem rozrywki</em>  z warstwy słownego symbolu ukazało prawdziwą formę. Gigantyczną. Dawno nie byłem w czymś podobnym i…dużym?<sup><a href=\"#user-content-pl-2026-05-analiza-ryzyka-na-wyjazdach-fn-4\" id=\"user-content-pl-2026-05-analiza-ryzyka-na-wyjazdach-fnref-4\" data-footnote-ref aria-describedby=\"footnote-label\">1</a></sup></p>\n<p>Technicznie tego dnia byłem z plecakiem, więc szaleństwa nie wchodziły w grę, ale za dużo już jeżdżę<sup><a href=\"#user-content-pl-2026-05-analiza-ryzyka-na-wyjazdach-fn-1\" id=\"user-content-pl-2026-05-analiza-ryzyka-na-wyjazdach-fnref-1\" data-footnote-ref aria-describedby=\"footnote-label\">2</a></sup>, także kolejnego dnia wróciłem tam gotowy po więcej.</p>\n<p>Patrząc na te gigantyczne kolejki z jednej strony miałem duży apetyt na przygodę, z innej strony byłem świadom swoich ograniczeń - tego że w końcu jestem osobą po udarze i decyzja o rollercoasterze może nie być najrozsądniejszą decyzją w moim życiu. W każdym razie chęć przygody wygrała i poszedłem na kolejkę <em>Insider</em> - w dialogu wewnętrznym czułem że kolejka bez punktów odniesienia w ciemności będzie doświadczeniem bardziej  intensywnym przy mniejszej trasie i mniejszych prędkościach.</p>\n<p>I myśląc o tych wszystkich przypadkach udarów i skrzepach zatykających tętnice udałem się tam<sup><a href=\"#user-content-pl-2026-05-analiza-ryzyka-na-wyjazdach-fn-2\" id=\"user-content-pl-2026-05-analiza-ryzyka-na-wyjazdach-fnref-2\" data-footnote-ref aria-describedby=\"footnote-label\">3</a></sup> wchodząc w ciemność…</p>\n<p>…pierdolnąłem w lustro okularami, bo ktoś uznał za potrzebne wrzucenie labiryntu luster na sam początek trasy. Sama trasa fajna, ale najbardziej stresujący był wypadający telefon z kieszeni, co nie pozwoliło w pełni delektować się adrenaliną.</p>\n<p>Stąd też  strasznie mnie śmieszy że obawiając się innych zagrożeń można spotkać zupełne inne<sup><a href=\"#user-content-pl-2026-05-analiza-ryzyka-na-wyjazdach-fn-3\" id=\"user-content-pl-2026-05-analiza-ryzyka-na-wyjazdach-fnref-3\" data-footnote-ref aria-describedby=\"footnote-label\">4</a></sup>.</p>\n<section data-footnotes class=\"footnotes\"><h2 class=\"sr-only\" id=\"footnote-label\">Footnotes</h2>\n<ol>\n<li id=\"user-content-pl-2026-05-analiza-ryzyka-na-wyjazdach-fn-4\">\n<p>Takie parki rozrywki przyjeżdżające do Olsztyna kojarzą mi się z latami 90-00, ale od tamtej pory nigdy nie spotkałem czegoś tak dużego. <a href=\"#user-content-pl-2026-05-analiza-ryzyka-na-wyjazdach-fnref-4\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-pl-2026-05-analiza-ryzyka-na-wyjazdach-fn-1\">\n<p>Stąd też wiem że branie hoteli ma tą zaletę że często można zostawić bagaż - i czasami też na dłużej niż jeden dzień <a href=\"#user-content-pl-2026-05-analiza-ryzyka-na-wyjazdach-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 2\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-pl-2026-05-analiza-ryzyka-na-wyjazdach-fn-2\">\n<p>Miałem raz w życiu podejście do Krav-Magi, gdzie bycie przewróconym na matę uważam za doświadczenie dość ożywcze - z samej aktywności zrezygnowałem gdzie neurolog sugerował że to może nie być najbardziej korzystne. <a href=\"#user-content-pl-2026-05-analiza-ryzyka-na-wyjazdach-fnref-2\" data-footnote-backref=\"\" aria-label=\"Back to reference 3\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-pl-2026-05-analiza-ryzyka-na-wyjazdach-fn-3\">\n<p>Którymi też się przejmowałem i obawiałem, ale terapia z waty cukrowej wyjątkowo złagodziła objawy. <a href=\"#user-content-pl-2026-05-analiza-ryzyka-na-wyjazdach-fnref-3\" data-footnote-backref=\"\" aria-label=\"Back to reference 4\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",[],"pl/2025/11/roznica-miedzy-rezonansem-medycznym-wykonanym-prywatnie-a-na-nfz",{id:470,data:472,body:477,filePath:478,digest:479,rendered:480},{title:473,date:474,tags:475,draft:51,thread:336},"Róznica między rezonansem medycznym wykonanym prywatnie, a na NFZ",["Date","2025-11-17T19:02:47.872Z"],[334,476],"medycyna","Z takich zabawnych anegdot to cały czas za mną chodzi różnica w doświadczeniu między rezonansem który miałem w ramach Luxmedu, kontra  rezonansem wykonanym na fundusz zdrowia.\n\nWłaściwie największą różnicą jest muzyka. W Luxmedzie dostajesz słuchawki, natomiast w publicznie finansowanym badaniu do dyspozycji masz najtańsze zatyczki.\n\nHumorystyczny też był dla mni aspekt[^1] że dopiero na tym którymś badaniu z rzędu, właśnie wykobywanym na fundusz moja głowa była przeskanowana wykrywaczem metali.  Jakby okej,  standardy diagnostyczne są mi już z doświadczenia bliskie, ale mimo te pierwsze badania było ze wszechmiar stresujące, biorąc pod uwagi że trzy czwarte badań na początku udaru były wykonywane gdy byłem niprzytomny to stres że mam w głowie jakieś rosyjskie[^2] nożyczki. Nie ukrywam, że ten symboliczny gest przed pierwszym badaniem w Polsce byłby dość mocno uspokający. \n\n\n[^1]: Jakby tak, mnie śmieszą dziwne rzeczy, możecie się przyzwyzcaić.\n\n[^2]: Tak, operację miałem w Rosji. To się nazywa niezwykła  pamiątka z podróży!","src/content/thoughts/pl/2025/11/roznica-miedzy-rezonansem-medycznym-wykonanym-prywatnie-a-na-nfz.md","ae862a2e4c20fa60",{html:481,metadata:482},"<p>Z takich zabawnych anegdot to cały czas za mną chodzi różnica w doświadczeniu między rezonansem który miałem w ramach Luxmedu, kontra  rezonansem wykonanym na fundusz zdrowia.</p>\n<p>Właściwie największą różnicą jest muzyka. W Luxmedzie dostajesz słuchawki, natomiast w publicznie finansowanym badaniu do dyspozycji masz najtańsze zatyczki.</p>\n<p>Humorystyczny też był dla mni aspekt<sup><a href=\"#user-content-fn-1\" id=\"user-content-fnref-1\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">1</a></sup> że dopiero na tym którymś badaniu z rzędu, właśnie wykobywanym na fundusz moja głowa była przeskanowana wykrywaczem metali.  Jakby okej,  standardy diagnostyczne są mi już z doświadczenia bliskie, ale mimo te pierwsze badania było ze wszechmiar stresujące, biorąc pod uwagi że trzy czwarte badań na początku udaru były wykonywane gdy byłem niprzytomny to stres że mam w głowie jakieś rosyjskie<sup><a href=\"#user-content-fn-2\" id=\"user-content-fnref-2\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">2</a></sup> nożyczki. Nie ukrywam, że ten symboliczny gest przed pierwszym badaniem w Polsce byłby dość mocno uspokający.</p>\n<section data-footnotes=\"\" class=\"footnotes\"><h2 class=\"\" id=\"footnote-label\">Przypisy</h2>\n<ol>\n<li id=\"user-content-fn-1\">\n<p>Jakby tak, mnie śmieszą dziwne rzeczy, możecie się przyzwyzcaić. <a href=\"#user-content-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-fn-2\">\n<p>Tak, operację miałem w Rosji. To się nazywa niezwykła  pamiątka z podróży! <a href=\"#user-content-fnref-2\" data-footnote-backref=\"\" aria-label=\"Back to reference 2\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",{headings:483,localImagePaths:485,remoteImagePaths:486,frontmatter:487,imagePaths:491},[484],{depth:28,slug:29,text:160},[],[],{title:473,date:488,tags:489,thread:336,draft:51,lang:166,previewHtml:490},["Date","2025-11-17T19:02:47.872Z"],[334,476],"<p>Z takich zabawnych anegdot to cały czas za mną chodzi różnica w doświadczeniu między rezonansem który miałem w ramach Luxmedu, kontra  rezonansem wykonanym na fundusz zdrowia.</p>\n<p>Właściwie największą różnicą jest muzyka. W Luxmedzie dostajesz słuchawki, natomiast w publicznie finansowanym badaniu do dyspozycji masz najtańsze zatyczki.</p>\n<p>Humorystyczny też był dla mni aspekt<sup><a href=\"#user-content-pl-2025-11-roznica-miedzy-rezonansem-medycznym-wykonanym-prywatnie-a-na-nfz-fn-1\" id=\"user-content-pl-2025-11-roznica-miedzy-rezonansem-medycznym-wykonanym-prywatnie-a-na-nfz-fnref-1\" data-footnote-ref aria-describedby=\"footnote-label\">1</a></sup> że dopiero na tym którymś badaniu z rzędu, właśnie wykobywanym na fundusz moja głowa była przeskanowana wykrywaczem metali.  Jakby okej,  standardy diagnostyczne są mi już z doświadczenia bliskie, ale mimo te pierwsze badania było ze wszechmiar stresujące, biorąc pod uwagi że trzy czwarte badań na początku udaru były wykonywane gdy byłem niprzytomny to stres że mam w głowie jakieś rosyjskie<sup><a href=\"#user-content-pl-2025-11-roznica-miedzy-rezonansem-medycznym-wykonanym-prywatnie-a-na-nfz-fn-2\" id=\"user-content-pl-2025-11-roznica-miedzy-rezonansem-medycznym-wykonanym-prywatnie-a-na-nfz-fnref-2\" data-footnote-ref aria-describedby=\"footnote-label\">2</a></sup> nożyczki. Nie ukrywam, że ten symboliczny gest przed pierwszym badaniem w Polsce byłby dość mocno uspokający.</p>\n<section data-footnotes class=\"footnotes\"><h2 class=\"sr-only\" id=\"footnote-label\">Footnotes</h2>\n<ol>\n<li id=\"user-content-pl-2025-11-roznica-miedzy-rezonansem-medycznym-wykonanym-prywatnie-a-na-nfz-fn-1\">\n<p>Jakby tak, mnie śmieszą dziwne rzeczy, możecie się przyzwyzcaić. <a href=\"#user-content-pl-2025-11-roznica-miedzy-rezonansem-medycznym-wykonanym-prywatnie-a-na-nfz-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-pl-2025-11-roznica-miedzy-rezonansem-medycznym-wykonanym-prywatnie-a-na-nfz-fn-2\">\n<p>Tak, operację miałem w Rosji. To się nazywa niezwykła  pamiątka z podróży! <a href=\"#user-content-pl-2025-11-roznica-miedzy-rezonansem-medycznym-wykonanym-prywatnie-a-na-nfz-fnref-2\" data-footnote-backref=\"\" aria-label=\"Back to reference 2\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",[],"pl/2025/11/stack-pt-1",{id:492,data:494,body:502,filePath:503,digest:504,rendered:505},{title:495,date:496,tags:497,translationKey:360,draft:19},"Aktualne podejście do stacku około-AI",["Date","2025-11-12T00:00:00.000Z"],[498,277,499,500,501],"AI","MCP","Programowanie","Programowanie/typescript","Jak wyglądają moje AI-owe preferencje na dzień dzisiejszy?\n\n## Edytor\n\nJakkolwiek fajnie mi się bawi za pomocą  vscodowego copilota, to limit tam zuzywam strasznie szybko [^1]\n\n## Update 2025-11-13\n\nJuż refaktoruję lol\n\n[^1]: Jakby jest 13 listopada a u mnie juz 90% zeszło...","src/content/thoughts/pl/2025/11/stack-pt-1.md","daddd7e3cfbaf369",{html:506,metadata:507},"<p>Jak wyglądają moje AI-owe preferencje na dzień dzisiejszy?</p>\n<h2 id=\"edytor\">Edytor</h2>\n<p>Jakkolwiek fajnie mi się bawi za pomocą  vscodowego copilota, to limit tam zuzywam strasznie szybko <sup><a href=\"#user-content-fn-1\" id=\"user-content-fnref-1\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">1</a></sup></p>\n<h2 id=\"update-2025-11-13\">Update 2025-11-13</h2>\n<p>Już refaktoruję lol</p>\n<section data-footnotes=\"\" class=\"footnotes\"><h2 class=\"\" id=\"footnote-label\">Przypisy</h2>\n<ol>\n<li id=\"user-content-fn-1\">\n<p>Jakby jest 13 listopada a u mnie juz 90% zeszło… <a href=\"#user-content-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",{headings:508,localImagePaths:516,remoteImagePaths:517,frontmatter:518,imagePaths:522},[509,512,515],{depth:28,slug:510,text:511},"edytor","Edytor",{depth:28,slug:513,text:514},"update-2025-11-13","Update 2025-11-13",{depth:28,slug:29,text:160},[],[],{title:495,date:519,tags:520,translationKey:360,draft:19,previewHtml:521},["Date","2025-11-12T00:00:00.000Z"],[498,277,499,500,501],"<p>Jak wyglądają moje AI-owe preferencje na dzień dzisiejszy?</p>\n<h2>Edytor</h2>\n<p>Jakkolwiek fajnie mi się bawi za pomocą  vscodowego copilota, to limit tam zuzywam strasznie szybko <sup><a href=\"#user-content-pl-2025-11-stack-pt-1-fn-1\" id=\"user-content-pl-2025-11-stack-pt-1-fnref-1\" data-footnote-ref aria-describedby=\"footnote-label\">1</a></sup></p>\n<h2>Update 2025-11-13</h2>\n<p>Już refaktoruję lol</p>\n<section data-footnotes class=\"footnotes\"><h2 class=\"sr-only\" id=\"footnote-label\">Footnotes</h2>\n<ol>\n<li id=\"user-content-pl-2025-11-stack-pt-1-fn-1\">\n<p>Jakby jest 13 listopada a u mnie juz 90% zeszło… <a href=\"#user-content-pl-2025-11-stack-pt-1-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",[],"pl/2025/11/uzyte-artykuy-w-trakcie-tworzenia-tego-bloga",{id:523,data:525,body:530,filePath:531,digest:532,rendered:533},{title:526,date:527,tags:528,translationKey:18,draft:51},"Użyte artykuły w trakcie tworzenia tego bloga",["Date","2025-11-13T07:57:25.728Z"],[529],"Web-dev","- Szukając fajnych statystyk Perplexity podrzuciło mi [Goatcounter](https://www.goatcounter.com/) - plus że open source i zaletą jest brak przymusu ostrzeżenia o ciasteczkach. Jak wyjdzie? Zobaczymy.","src/content/thoughts/pl/2025/11/uzyte-artykuy-w-trakcie-tworzenia-tego-bloga.md","bdb50fe7f24c85bb",{html:534,metadata:535},"<ul>\n<li>Szukając fajnych statystyk Perplexity podrzuciło mi <a href=\"https://www.goatcounter.com/\">Goatcounter</a> - plus że open source i zaletą jest brak przymusu ostrzeżenia o ciasteczkach. Jak wyjdzie? Zobaczymy.</li>\n</ul>",{headings:536,localImagePaths:537,remoteImagePaths:538,frontmatter:539,imagePaths:543},[],[],[],{title:526,description:540,date:541,tags:542,draft:51,lang:166,translationKey:18,previewHtml:534},"A new post about web-dev",["Date","2025-11-13T07:57:25.728Z"],[529],[],"pl/2025/11/w-warminsko-mazurskim-nic-sie-nie-dzieje-ale",{id:544,data:546,body:550,filePath:551,digest:552,rendered:553},{title:547,date:548,tags:549,draft:51},"W warmińsko-mazurskim nic sie nie dzieje, ale...",["Date","2025-11-15T15:23:35.602Z"],[205,176,204],"W te wakacje miałem dość dużą hiperfiksację związaną z podróżami[^1] na festiwale - jedna ciekawostka mi zapadła w pamięć sczególnie.\n\nSzukając alternatyw transportowych jak trafić do Holandii, Claude podpowiedział mi istnienie lotniska Weeze pod Duseldorfem w Niemczech - tak się składa że są tam loty z Szyman, naszego lokalnego, podolsztyńskiego lotniska - w dodatku zazwyczaj względnie tanie[^2]. I z jednej strony można to traktować jako fast travel pod Holandię, czy też zachodnie Niemcy.\n\n\nZ drugiej: to miejsce gdzie odbywa się [Parookaville](https://www.parookaville.com/en/), dość duży festiwal muzyki elektronicznej. \n\nChciałbym akurat to wiedzieć wcześniej - korzystałbym.\n\n\n\n\n[^1]: Czy od dwóch miesięcy dojeżdżam ponad 500km na praktyki w jedną stronę? Tak, i trochę mi mało...\n\n[^2]: Można się tylko domyślać, że ten samolot zazwyczaj wozi powietrze","src/content/thoughts/pl/2025/11/w-warminsko-mazurskim-nic-sie-nie-dzieje-ale.md","648c099d617f9599",{html:554,metadata:555},"<p>W te wakacje miałem dość dużą hiperfiksację związaną z podróżami<sup><a href=\"#user-content-fn-1\" id=\"user-content-fnref-1\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">1</a></sup> na festiwale - jedna ciekawostka mi zapadła w pamięć sczególnie.</p>\n<p>Szukając alternatyw transportowych jak trafić do Holandii, Claude podpowiedział mi istnienie lotniska Weeze pod Duseldorfem w Niemczech - tak się składa że są tam loty z Szyman, naszego lokalnego, podolsztyńskiego lotniska - w dodatku zazwyczaj względnie tanie<sup><a href=\"#user-content-fn-2\" id=\"user-content-fnref-2\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">2</a></sup>. I z jednej strony można to traktować jako fast travel pod Holandię, czy też zachodnie Niemcy.</p>\n<p>Z drugiej: to miejsce gdzie odbywa się <a href=\"https://www.parookaville.com/en/\">Parookaville</a>, dość duży festiwal muzyki elektronicznej.</p>\n<p>Chciałbym akurat to wiedzieć wcześniej - korzystałbym.</p>\n<section data-footnotes=\"\" class=\"footnotes\"><h2 class=\"\" id=\"footnote-label\">Przypisy</h2>\n<ol>\n<li id=\"user-content-fn-1\">\n<p>Czy od dwóch miesięcy dojeżdżam ponad 500km na praktyki w jedną stronę? Tak, i trochę mi mało… <a href=\"#user-content-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-fn-2\">\n<p>Można się tylko domyślać, że ten samolot zazwyczaj wozi powietrze <a href=\"#user-content-fnref-2\" data-footnote-backref=\"\" aria-label=\"Back to reference 2\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",{headings:556,localImagePaths:558,remoteImagePaths:559,frontmatter:560,imagePaths:565},[557],{depth:28,slug:29,text:160},[],[],{title:547,description:561,date:562,tags:563,draft:51,lang:166,previewHtml:564},"A new post about Europa, Protipy, podróże",["Date","2025-11-15T15:23:35.602Z"],[205,176,204],"<p>W te wakacje miałem dość dużą hiperfiksację związaną z podróżami<sup><a href=\"#user-content-pl-2025-11-w-warminsko-mazurskim-nic-sie-nie-dzieje-ale-fn-1\" id=\"user-content-pl-2025-11-w-warminsko-mazurskim-nic-sie-nie-dzieje-ale-fnref-1\" data-footnote-ref aria-describedby=\"footnote-label\">1</a></sup> na festiwale - jedna ciekawostka mi zapadła w pamięć sczególnie.</p>\n<p>Szukając alternatyw transportowych jak trafić do Holandii, Claude podpowiedział mi istnienie lotniska Weeze pod Duseldorfem w Niemczech - tak się składa że są tam loty z Szyman, naszego lokalnego, podolsztyńskiego lotniska - w dodatku zazwyczaj względnie tanie<sup><a href=\"#user-content-pl-2025-11-w-warminsko-mazurskim-nic-sie-nie-dzieje-ale-fn-2\" id=\"user-content-pl-2025-11-w-warminsko-mazurskim-nic-sie-nie-dzieje-ale-fnref-2\" data-footnote-ref aria-describedby=\"footnote-label\">2</a></sup>. I z jednej strony można to traktować jako fast travel pod Holandię, czy też zachodnie Niemcy.</p>\n<p>Z drugiej: to miejsce gdzie odbywa się <a href=\"https://www.parookaville.com/en/\">Parookaville</a>, dość duży festiwal muzyki elektronicznej.</p>\n<p>Chciałbym akurat to wiedzieć wcześniej - korzystałbym.</p>\n<section data-footnotes class=\"footnotes\"><h2 class=\"sr-only\" id=\"footnote-label\">Footnotes</h2>\n<ol>\n<li id=\"user-content-pl-2025-11-w-warminsko-mazurskim-nic-sie-nie-dzieje-ale-fn-1\">\n<p>Czy od dwóch miesięcy dojeżdżam ponad 500km na praktyki w jedną stronę? Tak, i trochę mi mało… <a href=\"#user-content-pl-2025-11-w-warminsko-mazurskim-nic-sie-nie-dzieje-ale-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-pl-2025-11-w-warminsko-mazurskim-nic-sie-nie-dzieje-ale-fn-2\">\n<p>Można się tylko domyślać, że ten samolot zazwyczaj wozi powietrze <a href=\"#user-content-pl-2025-11-w-warminsko-mazurskim-nic-sie-nie-dzieje-ale-fnref-2\" data-footnote-backref=\"\" aria-label=\"Back to reference 2\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",[],"pl/2025/11/przyjdzie-informatyk-na-wydzial-humanistyczny",{id:566,data:568,body:580,filePath:581,digest:582,rendered:583},{title:569,date:570,tags:571,relations:575,draft:51,thread:579},"Przyjdzie informatyk na wydział humanistyczny...",["Date","2025-11-14T00:00:00.000Z"],[83,572,573,574],"Praca Magisterska","Działalność Akademicka","Narzędzia",[576],{type:577,post:578},"continuation",{id:77,collection:9},"academia","Zaczynając pracę magisterską w realiach Wydziału Humanistycznego przyszedłem z dość fajnym bagażem - czy też doświadczeniem pisania w Zotero. Co prawda styl cytowania zgoła odmienny od tego co znałem dotychczas, ale gdyby ktoś kiedyś trafił w podobnych realiach i chciał mieć fajne narzędzie do zarządzania bibliografią - czuję potrzebę napomknąć że jest styl cytowania w polskich naukach humanistycznych - jest dostępny pod [tym adresem](http://metodyka.upjp2.edu.pl/book:zotero)[^1]\n\n[^1]: Czy finalnie aby wstrzelić się w w wymagania wydziałowe odnośnie bibliografii całość i tak przeszła przez LLM, aby spełnić wymagania odnośnie formatu imion? Tak, ale ciii.","src/content/thoughts/pl/2025/11/przyjdzie-informatyk-na-wydzial-humanistyczny.md","39eee629f59cc6c2",{html:584,metadata:585},"<p>Zaczynając pracę magisterską w realiach Wydziału Humanistycznego przyszedłem z dość fajnym bagażem - czy też doświadczeniem pisania w Zotero. Co prawda styl cytowania zgoła odmienny od tego co znałem dotychczas, ale gdyby ktoś kiedyś trafił w podobnych realiach i chciał mieć fajne narzędzie do zarządzania bibliografią - czuję potrzebę napomknąć że jest styl cytowania w polskich naukach humanistycznych - jest dostępny pod <a href=\"http://metodyka.upjp2.edu.pl/book:zotero\">tym adresem</a><sup><a href=\"#user-content-fn-1\" id=\"user-content-fnref-1\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">1</a></sup></p>\n<section data-footnotes=\"\" class=\"footnotes\"><h2 class=\"\" id=\"footnote-label\">Przypisy</h2>\n<ol>\n<li id=\"user-content-fn-1\">\n<p>Czy finalnie aby wstrzelić się w w wymagania wydziałowe odnośnie bibliografii całość i tak przeszła przez LLM, aby spełnić wymagania odnośnie formatu imion? Tak, ale ciii. <a href=\"#user-content-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",{headings:586,localImagePaths:588,remoteImagePaths:589,frontmatter:590,imagePaths:597},[587],{depth:28,slug:29,text:160},[],[],{title:569,description:591,date:592,tags:593,thread:579,draft:51,lang:166,relations:594,previewHtml:596},"A new post about zotero",["Date","2025-11-14T00:00:00.000Z"],[83,572,573,574],[595],{type:577,post:77},"<p>Zaczynając pracę magisterską w realiach Wydziału Humanistycznego przyszedłem z dość fajnym bagażem - czy też doświadczeniem pisania w Zotero. Co prawda styl cytowania zgoła odmienny od tego co znałem dotychczas, ale gdyby ktoś kiedyś trafił w podobnych realiach i chciał mieć fajne narzędzie do zarządzania bibliografią - czuję potrzebę napomknąć że jest styl cytowania w polskich naukach humanistycznych - jest dostępny pod <a href=\"http://metodyka.upjp2.edu.pl/book:zotero\">tym adresem</a><sup><a href=\"#user-content-pl-2025-11-przyjdzie-informatyk-na-wydzial-humanistyczny-fn-1\" id=\"user-content-pl-2025-11-przyjdzie-informatyk-na-wydzial-humanistyczny-fnref-1\" data-footnote-ref aria-describedby=\"footnote-label\">1</a></sup></p>\n<section data-footnotes class=\"footnotes\"><h2 class=\"sr-only\" id=\"footnote-label\">Footnotes</h2>\n<ol>\n<li id=\"user-content-pl-2025-11-przyjdzie-informatyk-na-wydzial-humanistyczny-fn-1\">\n<p>Czy finalnie aby wstrzelić się w w wymagania wydziałowe odnośnie bibliografii całość i tak przeszła przez LLM, aby spełnić wymagania odnośnie formatu imion? Tak, ale ciii. <a href=\"#user-content-pl-2025-11-przyjdzie-informatyk-na-wydzial-humanistyczny-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",[],"pl/2026/09/jak-zalogowac-sie-do-grafany-przez-authelia-jako-admin",{id:598,data:600,body:610,filePath:611,assetImports:612,digest:614,rendered:615},{title:601,date:602,tags:603,draft:51},"Jak zalogować się do Grafany przez Authelię jako admin?",["Date","2026-09-13T17:32:54.131Z"],[604,605,606,607,608,609],"grafana","authelia","devops","oidc","oauth","monitoring","Ostatnio hobbystycznie wracam do zabawy w selfhosting — jeden z tych okresowych nawrotów, gdzie na nowo można rozwiązać stare problemy, testując różne podejścia do rzeczy, które kiedyś już \"rozwiązałem\"[^1]. Tym razem przyszła kolej na monitoring.\n\nZdziwiło mnie, że zaraz po skonfigurowaniu OIDC nie mogłem dodać żadnego dashboardu w Grafanie — logowanie działało, a mimo to brakowało uprawnień.\n\n## Setup\n\nGrafana stała już za Authelią (self-hosted SSO, jeden użytkownik, w grupie `admins`) przez natywne OIDC[^2] (`auth.generic_oauth`). Zadanie wydawało się trywialne: każdy z grupy `admins` ma dostawać rolę `GrafanaAdmin` w Grafanie automatycznie przy logowaniu, zamiast nadać ręcznie w UI — i tak zostałoby nadpisane przy każdym logowaniu, bo `allow_sign_up: true` re-provisionuje usera za każdym razem.\n\n## Grafana\n\nStandardowa, udokumentowana ścieżka: scope `groups` na kliencie OIDC + `role_attribute_path` (wyrażenie JMESPath[^3]) po stronie Grafany.\n\nGrafanę stawiam przez Ansible, rolą [`grafana.grafana.grafana`](https://github.com/grafana/grafana-ansible-collection). Najważniejszy fragment configu to zmienna `grafana_ini_oauth`:\n\n```yaml\ngrafana_ini_oauth:\n  \"auth.generic_oauth\":\n    enabled: true\n    name: Authelia\n    client_id: grafana\n    client_secret: \"{{ grafana_authelia_oidc_secret | default('') }}\"\n    scopes: \"openid profile email groups\"\n    auth_url: \"https://authelia.example.com/api/oidc/authorization\"\n    token_url: \"https://authelia.example.com/api/oidc/token\"\n    api_url: \"https://authelia.example.com/api/oidc/userinfo\"\n    use_pkce: true\n    allow_sign_up: true\n    role_attribute_path: \"contains(groups[*], 'admins') && 'GrafanaAdmin' || 'Viewer'\"\n```\n\nAdmin user jest jedynym członkiem grupy `admins` w Authelii — stąd `contains(groups[*], 'admins')` w wyrażeniu wyżej. Warunek konieczny, żeby to zadziałało: scope `groups` musi być dodany do klienta OIDC Grafany, tak jak w configu powyżej.\n\n## Co miało się wydarzyć\n\nDokumentacja `role_attribute_path` w Grafanie opisuje trójstopniowy fallback: najpierw `id_token`, jeśli nic nie znajdzie — `userinfo` (`api_url`), jeśli nadal nic — `access_token`. Brzmi jak solidna redundancja.\n\n## Co się wydarzyło w praktyce\n\nW Grafanie 13.2.1 fallback do `userinfo` jest zepsuty — potwierdzone przez [grafana/grafana#106686](https://github.com/grafana/grafana/issues/106686). Jeśli claima nie ma w `id_token`, Grafana nie sprawdza `userinfo` tak, jak deklaruje dokumentacja.\n\nTymczasem Authelia od wersji 4.39 przestała domyślnie wrzucać claimy ze scope'ów (np. `groups`) do `id_token` — trafiają tylko do `userinfo`. To sensowne zaostrzenie bezpieczeństwa samo w sobie (mniej PII w tokenie, który trafia do różnych stron), ale w zderzeniu ze zepsutym fallbackiem Grafany daje cichy blackout: dokładnie ten claim, który ma znaczenie dla roli, nigdzie nie dociera.[^4]\n\n## Fix po stronie Authelii\n\n`identity_providers.oidc.claims_policies` po stronie Authelii — jawnie wymusza konkretne claimy z powrotem do `id_token` per-klient, referencjonowane z klienta przez `claims_policy: <nazwa>`.\n\n```yaml\nidentity_providers:\n  oidc:\n    # ...\n    claims_policies:\n      grafana: # nazwa polityki, dowolna, referencjonowana niżej\n        id_token:\n          - 'groups' # wymuś ten claim do id_tokenu\n\n    clients:\n      - client_id: 'inny'\n        # brak claims_policy — nie dostaje tego traktowania\n\n      - client_id: 'grafana'\n        client_secret: '...'\n        claims_policy: 'grafana' # podłączenie polityki do klienta\n        redirect_uris:\n          - 'https://grafana.example.com/login/generic_oauth'\n        scopes:\n          - 'openid'\n          - 'profile'\n          - 'email'\n          - 'groups' # musi być zażądany, inaczej nic do wymuszenia\n```\n\nZ tymi ustawieniami ponownie można logować się do Grafany jako admin — kolejny stary problem odhaczony, na nowo i inaczej niż ostatnim razem.\n\nI czy, mając możliwość dodania dashboardu, dodałem go?\n\n![Pingu siedzący na krześle z napisem \"TERAZ JUŻ NIE CHCĘ\"](@assets/images/pingu-teraz-juz-nie-chce.png \"teraz już nie chcę\")\n\n[^1]: [RPi-Monitor](https://github.com/RPi-Monitor/RPi-Monitor), pamiętamy\n[^2]: OIDC (OpenID Connect) — protokół logowania (SSO) zbudowany na OAuth2.\n[^3]: [JMESPath](https://jmespath.org/) — język zapytań do wyciągania i przekształcania danych z dokumentów JSON, tu używany do wyciągnięcia grup z claimów tokenu.\n[^4]: Kto się naszukał, jak dodać nowy dashboard, żeby po dłuższej chwili zorientować się, że ma tylko Viewera? Autor.","src/content/thoughts/pl/2026/09/jak-zalogowac-sie-do-grafany-przez-authelia-jako-admin.md",[613],"../../../../../assets/images/pingu-teraz-juz-nie-chce.png","0e9066efb6d7ce93",{html:616,metadata:617},"<p>Ostatnio hobbystycznie wracam do zabawy w selfhosting — jeden z tych okresowych nawrotów, gdzie na nowo można rozwiązać stare problemy, testując różne podejścia do rzeczy, które kiedyś już “rozwiązałem”<sup><a href=\"#user-content-fn-1\" id=\"user-content-fnref-1\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">1</a></sup>. Tym razem przyszła kolej na monitoring.</p>\n<p>Zdziwiło mnie, że zaraz po skonfigurowaniu OIDC nie mogłem dodać żadnego dashboardu w Grafanie — logowanie działało, a mimo to brakowało uprawnień.</p>\n<h2 id=\"setup\">Setup</h2>\n<p>Grafana stała już za Authelią (self-hosted SSO, jeden użytkownik, w grupie <code>admins</code>) przez natywne OIDC<sup><a href=\"#user-content-fn-2\" id=\"user-content-fnref-2\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">2</a></sup> (<code>auth.generic_oauth</code>). Zadanie wydawało się trywialne: każdy z grupy <code>admins</code> ma dostawać rolę <code>GrafanaAdmin</code> w Grafanie automatycznie przy logowaniu, zamiast nadać ręcznie w UI — i tak zostałoby nadpisane przy każdym logowaniu, bo <code>allow_sign_up: true</code> re-provisionuje usera za każdym razem.</p>\n<h2 id=\"grafana\">Grafana</h2>\n<p>Standardowa, udokumentowana ścieżka: scope <code>groups</code> na kliencie OIDC + <code>role_attribute_path</code> (wyrażenie JMESPath<sup><a href=\"#user-content-fn-3\" id=\"user-content-fnref-3\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">3</a></sup>) po stronie Grafany.</p>\n<p>Grafanę stawiam przez Ansible, rolą <a href=\"https://github.com/grafana/grafana-ansible-collection\"><code>grafana.grafana.grafana</code></a>. Najważniejszy fragment configu to zmienna <code>grafana_ini_oauth</code>:</p>\n<pre class=\"astro-code css-variables\" style=\"background-color:var(--astro-code-background);color:var(--astro-code-foreground); overflow-x: auto;\" tabindex=\"0\" data-language=\"yaml\"><code><span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">grafana_ini_oauth</span><span style=\"color:var(--astro-code-token-keyword)\">:</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-string-expression)\">  \"auth.generic_oauth\"</span><span style=\"color:var(--astro-code-token-keyword)\">:</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">    enabled</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-constant)\"> true</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">    name</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-string-expression)\"> Authelia</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">    client_id</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-string-expression)\"> grafana</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">    client_secret</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-string-expression)\"> \"{{ grafana_authelia_oidc_secret | default('') }}\"</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">    scopes</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-string-expression)\"> \"openid profile email groups\"</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">    auth_url</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-string-expression)\"> \"https://authelia.example.com/api/oidc/authorization\"</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">    token_url</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-string-expression)\"> \"https://authelia.example.com/api/oidc/token\"</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">    api_url</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-string-expression)\"> \"https://authelia.example.com/api/oidc/userinfo\"</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">    use_pkce</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-constant)\"> true</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">    allow_sign_up</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-constant)\"> true</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">    role_attribute_path</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-string-expression)\"> \"contains(groups[*], 'admins') &#x26;&#x26; 'GrafanaAdmin' || 'Viewer'\"</span></span></code></pre>\n<p>Admin user jest jedynym członkiem grupy <code>admins</code> w Authelii — stąd <code>contains(groups[*], 'admins')</code> w wyrażeniu wyżej. Warunek konieczny, żeby to zadziałało: scope <code>groups</code> musi być dodany do klienta OIDC Grafany, tak jak w configu powyżej.</p>\n<h2 id=\"co-miało-się-wydarzyć\">Co miało się wydarzyć</h2>\n<p>Dokumentacja <code>role_attribute_path</code> w Grafanie opisuje trójstopniowy fallback: najpierw <code>id_token</code>, jeśli nic nie znajdzie — <code>userinfo</code> (<code>api_url</code>), jeśli nadal nic — <code>access_token</code>. Brzmi jak solidna redundancja.</p>\n<h2 id=\"co-się-wydarzyło-w-praktyce\">Co się wydarzyło w praktyce</h2>\n<p>W Grafanie 13.2.1 fallback do <code>userinfo</code> jest zepsuty — potwierdzone przez <a href=\"https://github.com/grafana/grafana/issues/106686\">grafana/grafana#106686</a>. Jeśli claima nie ma w <code>id_token</code>, Grafana nie sprawdza <code>userinfo</code> tak, jak deklaruje dokumentacja.</p>\n<p>Tymczasem Authelia od wersji 4.39 przestała domyślnie wrzucać claimy ze scope’ów (np. <code>groups</code>) do <code>id_token</code> — trafiają tylko do <code>userinfo</code>. To sensowne zaostrzenie bezpieczeństwa samo w sobie (mniej PII w tokenie, który trafia do różnych stron), ale w zderzeniu ze zepsutym fallbackiem Grafany daje cichy blackout: dokładnie ten claim, który ma znaczenie dla roli, nigdzie nie dociera.<sup><a href=\"#user-content-fn-4\" id=\"user-content-fnref-4\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">4</a></sup></p>\n<h2 id=\"fix-po-stronie-authelii\">Fix po stronie Authelii</h2>\n<p><code>identity_providers.oidc.claims_policies</code> po stronie Authelii — jawnie wymusza konkretne claimy z powrotem do <code>id_token</code> per-klient, referencjonowane z klienta przez <code>claims_policy: &#x3C;nazwa></code>.</p>\n<pre class=\"astro-code css-variables\" style=\"background-color:var(--astro-code-background);color:var(--astro-code-foreground); overflow-x: auto;\" tabindex=\"0\" data-language=\"yaml\"><code><span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">identity_providers</span><span style=\"color:var(--astro-code-token-keyword)\">:</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">  oidc</span><span style=\"color:var(--astro-code-token-keyword)\">:</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-comment)\">    # ...</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">    claims_policies</span><span style=\"color:var(--astro-code-token-keyword)\">:</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">      grafana</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-comment)\"> # nazwa polityki, dowolna, referencjonowana niżej</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">        id_token</span><span style=\"color:var(--astro-code-token-keyword)\">:</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-foreground)\">          - </span><span style=\"color:var(--astro-code-token-string-expression)\">'groups'</span><span style=\"color:var(--astro-code-token-comment)\"> # wymuś ten claim do id_tokenu</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">    clients</span><span style=\"color:var(--astro-code-token-keyword)\">:</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-foreground)\">      - </span><span style=\"color:var(--astro-code-token-keyword)\">client_id</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-string-expression)\"> 'inny'</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-comment)\">        # brak claims_policy — nie dostaje tego traktowania</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-foreground)\">      - </span><span style=\"color:var(--astro-code-token-keyword)\">client_id</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-string-expression)\"> 'grafana'</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">        client_secret</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-string-expression)\"> '...'</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">        claims_policy</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-string-expression)\"> 'grafana'</span><span style=\"color:var(--astro-code-token-comment)\"> # podłączenie polityki do klienta</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">        redirect_uris</span><span style=\"color:var(--astro-code-token-keyword)\">:</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-foreground)\">          - </span><span style=\"color:var(--astro-code-token-string-expression)\">'https://grafana.example.com/login/generic_oauth'</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">        scopes</span><span style=\"color:var(--astro-code-token-keyword)\">:</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-foreground)\">          - </span><span style=\"color:var(--astro-code-token-string-expression)\">'openid'</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-foreground)\">          - </span><span style=\"color:var(--astro-code-token-string-expression)\">'profile'</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-foreground)\">          - </span><span style=\"color:var(--astro-code-token-string-expression)\">'email'</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-foreground)\">          - </span><span style=\"color:var(--astro-code-token-string-expression)\">'groups'</span><span style=\"color:var(--astro-code-token-comment)\"> # musi być zażądany, inaczej nic do wymuszenia</span></span></code></pre>\n<p>Z tymi ustawieniami ponownie można logować się do Grafany jako admin — kolejny stary problem odhaczony, na nowo i inaczej niż ostatnim razem.</p>\n<p>I czy, mając możliwość dodania dashboardu, dodałem go?</p>\n<p></p><figure class=\"post-figure\"><img __ASTRO_IMAGE_=\"{&#x22;src&#x22;:&#x22;../../../../../assets/images/pingu-teraz-juz-nie-chce.png&#x22;,&#x22;alt&#x22;:&#x22;Pingu siedzący na krześle z napisem \\&#x22;TERAZ JUŻ NIE CHCĘ\\&#x22;&#x22;,&#x22;index&#x22;:0}\"><figcaption>teraz już nie chcę</figcaption></figure><p></p>\n<section data-footnotes=\"\" class=\"footnotes\"><h2 class=\"\" id=\"footnote-label\">Przypisy</h2>\n<ol>\n<li id=\"user-content-fn-1\">\n<p><a href=\"https://github.com/RPi-Monitor/RPi-Monitor\">RPi-Monitor</a>, pamiętamy <a href=\"#user-content-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-fn-2\">\n<p>OIDC (OpenID Connect) — protokół logowania (SSO) zbudowany na OAuth2. <a href=\"#user-content-fnref-2\" data-footnote-backref=\"\" aria-label=\"Back to reference 2\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-fn-3\">\n<p><a href=\"https://jmespath.org/\">JMESPath</a> — język zapytań do wyciągania i przekształcania danych z dokumentów JSON, tu używany do wyciągnięcia grup z claimów tokenu. <a href=\"#user-content-fnref-3\" data-footnote-backref=\"\" aria-label=\"Back to reference 3\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-fn-4\">\n<p>Kto się naszukał, jak dodać nowy dashboard, żeby po dłuższej chwili zorientować się, że ma tylko Viewera? Autor. <a href=\"#user-content-fnref-4\" data-footnote-backref=\"\" aria-label=\"Back to reference 4\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",{headings:618,localImagePaths:634,remoteImagePaths:635,frontmatter:636,imagePaths:640},[619,622,624,627,630,633],{depth:28,slug:620,text:621},"setup","Setup",{depth:28,slug:604,text:623},"Grafana",{depth:28,slug:625,text:626},"co-miało-się-wydarzyć","Co miało się wydarzyć",{depth:28,slug:628,text:629},"co-się-wydarzyło-w-praktyce","Co się wydarzyło w praktyce",{depth:28,slug:631,text:632},"fix-po-stronie-authelii","Fix po stronie Authelii",{depth:28,slug:29,text:160},[613],[],{title:601,date:637,tags:638,draft:51,lang:166,previewHtml:639},["Date","2026-09-13T17:32:54.131Z"],[604,605,606,607,608,609],"<p>Ostatnio hobbystycznie wracam do zabawy w selfhosting — jeden z tych okresowych nawrotów, gdzie na nowo można rozwiązać stare problemy, testując różne podejścia do rzeczy, które kiedyś już “rozwiązałem”<sup><a href=\"#user-content-pl-2026-09-jak-zalogowac-sie-do-grafany-przez-authelia-jako-admin-fn-1\" id=\"user-content-pl-2026-09-jak-zalogowac-sie-do-grafany-przez-authelia-jako-admin-fnref-1\" data-footnote-ref aria-describedby=\"footnote-label\">1</a></sup>. Tym razem przyszła kolej na monitoring.</p>\n<p>Zdziwiło mnie, że zaraz po skonfigurowaniu OIDC nie mogłem dodać żadnego dashboardu w Grafanie — logowanie działało, a mimo to brakowało uprawnień.</p>\n<h2>Setup</h2>\n<p>Grafana stała już za Authelią (self-hosted SSO, jeden użytkownik, w grupie <code>admins</code>) przez natywne OIDC<sup><a href=\"#user-content-pl-2026-09-jak-zalogowac-sie-do-grafany-przez-authelia-jako-admin-fn-2\" id=\"user-content-pl-2026-09-jak-zalogowac-sie-do-grafany-przez-authelia-jako-admin-fnref-2\" data-footnote-ref aria-describedby=\"footnote-label\">2</a></sup> (<code>auth.generic_oauth</code>). Zadanie wydawało się trywialne: każdy z grupy <code>admins</code> ma dostawać rolę <code>GrafanaAdmin</code> w Grafanie automatycznie przy logowaniu, zamiast nadać ręcznie w UI — i tak zostałoby nadpisane przy każdym logowaniu, bo <code>allow_sign_up: true</code> re-provisionuje usera za każdym razem.</p>\n<h2>Grafana</h2>\n<p>Standardowa, udokumentowana ścieżka: scope <code>groups</code> na kliencie OIDC + <code>role_attribute_path</code> (wyrażenie JMESPath<sup><a href=\"#user-content-pl-2026-09-jak-zalogowac-sie-do-grafany-przez-authelia-jako-admin-fn-3\" id=\"user-content-pl-2026-09-jak-zalogowac-sie-do-grafany-przez-authelia-jako-admin-fnref-3\" data-footnote-ref aria-describedby=\"footnote-label\">3</a></sup>) po stronie Grafany.</p>\n<p>Grafanę stawiam przez Ansible, rolą <a href=\"https://github.com/grafana/grafana-ansible-collection\"><code>grafana.grafana.grafana</code></a>. Najważniejszy fragment configu to zmienna <code>grafana_ini_oauth</code>:</p>\n<pre class=\"astro-code css-variables\" style=\"background-color:var(--astro-code-background);color:var(--astro-code-foreground); overflow-x: auto;\" tabindex=\"0\" data-language=\"yaml\"><code><span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">grafana_ini_oauth</span><span style=\"color:var(--astro-code-token-keyword)\">:</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-string-expression)\">  \"auth.generic_oauth\"</span><span style=\"color:var(--astro-code-token-keyword)\">:</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">    enabled</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-constant)\"> true</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">    name</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-string-expression)\"> Authelia</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">    client_id</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-string-expression)\"> grafana</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">    client_secret</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-string-expression)\"> \"{{ grafana_authelia_oidc_secret | default('') }}\"</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">    scopes</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-string-expression)\"> \"openid profile email groups\"</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">    auth_url</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-string-expression)\"> \"https://authelia.example.com/api/oidc/authorization\"</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">    token_url</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-string-expression)\"> \"https://authelia.example.com/api/oidc/token\"</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">    api_url</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-string-expression)\"> \"https://authelia.example.com/api/oidc/userinfo\"</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">    use_pkce</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-constant)\"> true</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">    allow_sign_up</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-constant)\"> true</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">    role_attribute_path</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-string-expression)\"> \"contains(groups[*], 'admins') &#x26;&#x26; 'GrafanaAdmin' || 'Viewer'\"</span></span></code></pre>\n<p>Admin user jest jedynym członkiem grupy <code>admins</code> w Authelii — stąd <code>contains(groups[*], 'admins')</code> w wyrażeniu wyżej. Warunek konieczny, żeby to zadziałało: scope <code>groups</code> musi być dodany do klienta OIDC Grafany, tak jak w configu powyżej.</p>\n<h2>Co miało się wydarzyć</h2>\n<p>Dokumentacja <code>role_attribute_path</code> w Grafanie opisuje trójstopniowy fallback: najpierw <code>id_token</code>, jeśli nic nie znajdzie — <code>userinfo</code> (<code>api_url</code>), jeśli nadal nic — <code>access_token</code>. Brzmi jak solidna redundancja.</p>\n<h2>Co się wydarzyło w praktyce</h2>\n<p>W Grafanie 13.2.1 fallback do <code>userinfo</code> jest zepsuty — potwierdzone przez <a href=\"https://github.com/grafana/grafana/issues/106686\">grafana/grafana#106686</a>. Jeśli claima nie ma w <code>id_token</code>, Grafana nie sprawdza <code>userinfo</code> tak, jak deklaruje dokumentacja.</p>\n<p>Tymczasem Authelia od wersji 4.39 przestała domyślnie wrzucać claimy ze scope’ów (np. <code>groups</code>) do <code>id_token</code> — trafiają tylko do <code>userinfo</code>. To sensowne zaostrzenie bezpieczeństwa samo w sobie (mniej PII w tokenie, który trafia do różnych stron), ale w zderzeniu ze zepsutym fallbackiem Grafany daje cichy blackout: dokładnie ten claim, który ma znaczenie dla roli, nigdzie nie dociera.<sup><a href=\"#user-content-pl-2026-09-jak-zalogowac-sie-do-grafany-przez-authelia-jako-admin-fn-4\" id=\"user-content-pl-2026-09-jak-zalogowac-sie-do-grafany-przez-authelia-jako-admin-fnref-4\" data-footnote-ref aria-describedby=\"footnote-label\">4</a></sup></p>\n<h2>Fix po stronie Authelii</h2>\n<p><code>identity_providers.oidc.claims_policies</code> po stronie Authelii — jawnie wymusza konkretne claimy z powrotem do <code>id_token</code> per-klient, referencjonowane z klienta przez <code>claims_policy: &#x3C;nazwa></code>.</p>\n<pre class=\"astro-code css-variables\" style=\"background-color:var(--astro-code-background);color:var(--astro-code-foreground); overflow-x: auto;\" tabindex=\"0\" data-language=\"yaml\"><code><span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">identity_providers</span><span style=\"color:var(--astro-code-token-keyword)\">:</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">  oidc</span><span style=\"color:var(--astro-code-token-keyword)\">:</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-comment)\">    # ...</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">    claims_policies</span><span style=\"color:var(--astro-code-token-keyword)\">:</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">      grafana</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-comment)\"> # nazwa polityki, dowolna, referencjonowana niżej</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">        id_token</span><span style=\"color:var(--astro-code-token-keyword)\">:</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-foreground)\">          - </span><span style=\"color:var(--astro-code-token-string-expression)\">'groups'</span><span style=\"color:var(--astro-code-token-comment)\"> # wymuś ten claim do id_tokenu</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">    clients</span><span style=\"color:var(--astro-code-token-keyword)\">:</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-foreground)\">      - </span><span style=\"color:var(--astro-code-token-keyword)\">client_id</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-string-expression)\"> 'inny'</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-comment)\">        # brak claims_policy — nie dostaje tego traktowania</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-foreground)\">      - </span><span style=\"color:var(--astro-code-token-keyword)\">client_id</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-string-expression)\"> 'grafana'</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">        client_secret</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-string-expression)\"> '...'</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">        claims_policy</span><span style=\"color:var(--astro-code-token-keyword)\">:</span><span style=\"color:var(--astro-code-token-string-expression)\"> 'grafana'</span><span style=\"color:var(--astro-code-token-comment)\"> # podłączenie polityki do klienta</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">        redirect_uris</span><span style=\"color:var(--astro-code-token-keyword)\">:</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-foreground)\">          - </span><span style=\"color:var(--astro-code-token-string-expression)\">'https://grafana.example.com/login/generic_oauth'</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-token-keyword)\">        scopes</span><span style=\"color:var(--astro-code-token-keyword)\">:</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-foreground)\">          - </span><span style=\"color:var(--astro-code-token-string-expression)\">'openid'</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-foreground)\">          - </span><span style=\"color:var(--astro-code-token-string-expression)\">'profile'</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-foreground)\">          - </span><span style=\"color:var(--astro-code-token-string-expression)\">'email'</span></span>\n<span class=\"line\"><span style=\"color:var(--astro-code-foreground)\">          - </span><span style=\"color:var(--astro-code-token-string-expression)\">'groups'</span><span style=\"color:var(--astro-code-token-comment)\"> # musi być zażądany, inaczej nic do wymuszenia</span></span></code></pre>\n<p>Z tymi ustawieniami ponownie można logować się do Grafany jako admin — kolejny stary problem odhaczony, na nowo i inaczej niż ostatnim razem.</p>\n<p>I czy, mając możliwość dodania dashboardu, dodałem go?</p>\n<p><figure class=\"post-figure\"><img src=\"/__preview_asset__/assets/images/pingu-teraz-juz-nie-chce.png\" alt=\"Pingu siedzący na krześle z napisem &#x22;TERAZ JUŻ NIE CHCĘ&#x22;\"><figcaption>teraz już nie chcę</figcaption></figure></p>\n<section data-footnotes class=\"footnotes\"><h2 class=\"sr-only\" id=\"footnote-label\">Footnotes</h2>\n<ol>\n<li id=\"user-content-pl-2026-09-jak-zalogowac-sie-do-grafany-przez-authelia-jako-admin-fn-1\">\n<p><a href=\"https://github.com/RPi-Monitor/RPi-Monitor\">RPi-Monitor</a>, pamiętamy <a href=\"#user-content-pl-2026-09-jak-zalogowac-sie-do-grafany-przez-authelia-jako-admin-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-pl-2026-09-jak-zalogowac-sie-do-grafany-przez-authelia-jako-admin-fn-2\">\n<p>OIDC (OpenID Connect) — protokół logowania (SSO) zbudowany na OAuth2. <a href=\"#user-content-pl-2026-09-jak-zalogowac-sie-do-grafany-przez-authelia-jako-admin-fnref-2\" data-footnote-backref=\"\" aria-label=\"Back to reference 2\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-pl-2026-09-jak-zalogowac-sie-do-grafany-przez-authelia-jako-admin-fn-3\">\n<p><a href=\"https://jmespath.org/\">JMESPath</a> — język zapytań do wyciągania i przekształcania danych z dokumentów JSON, tu używany do wyciągnięcia grup z claimów tokenu. <a href=\"#user-content-pl-2026-09-jak-zalogowac-sie-do-grafany-przez-authelia-jako-admin-fnref-3\" data-footnote-backref=\"\" aria-label=\"Back to reference 3\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-pl-2026-09-jak-zalogowac-sie-do-grafany-przez-authelia-jako-admin-fn-4\">\n<p>Kto się naszukał, jak dodać nowy dashboard, żeby po dłuższej chwili zorientować się, że ma tylko Viewera? Autor. <a href=\"#user-content-pl-2026-09-jak-zalogowac-sie-do-grafany-przez-authelia-jako-admin-fnref-4\" data-footnote-backref=\"\" aria-label=\"Back to reference 4\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",[613],"pl/2026/04/w-koncu-live",{id:641,data:643,body:647,filePath:648,digest:649,rendered:650},{title:644,date:645,tags:646,draft:51},"Live",["Date","2026-04-19T12:48:03.195Z"],[277,203],"Po paru miesiącach dłubania[^1], post-Claude-Code hiperfiksacji na AI-owych sideprojektach — wracam do dłubania tego repozytorium, aka prowadzenia bloga.\n\n\nMam taki problem z polską komunikacją publiczną, że w pociągach PKP na trasie Olsztyn–Katowice zazwyczaj nie ma internetu. Jakieś 60% przejazdów. Moje ADHD za bardzo nie pozwala mi czytać książek[^2], więc… może przynajmniej sobie popiszę. Pouczę LLM-y. Zatruję je odrobiną nudnej wiedzy.\n\n_I tak, ten design jest z pachnącego świeżością Claude Design, gdzieniegdzie jeszcze widać stary styl który sukcesywnie będę poprawiał._\n\n[^1]: Jak widać po datach treść tych notatek trochę odleżała niczym dobry alkohol.\n\n[^2]: Największy akt desperacji to wyciąganie nmapa i analiza ruchu licząc na to, że  ręcznie uda mi się potwierdzić regulamin - bez skutku, niestety.","src/content/thoughts/pl/2026/04/w-koncu-live.md","f85716b1071966d5",{html:651,metadata:652},"<p>Po paru miesiącach dłubania<sup><a href=\"#user-content-fn-1\" id=\"user-content-fnref-1\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">1</a></sup>, post-Claude-Code hiperfiksacji na AI-owych sideprojektach — wracam do dłubania tego repozytorium, aka prowadzenia bloga.</p>\n<p>Mam taki problem z polską komunikacją publiczną, że w pociągach PKP na trasie Olsztyn–Katowice zazwyczaj nie ma internetu. Jakieś 60% przejazdów. Moje ADHD za bardzo nie pozwala mi czytać książek<sup><a href=\"#user-content-fn-2\" id=\"user-content-fnref-2\" data-footnote-ref=\"\" aria-describedby=\"footnote-label\">2</a></sup>, więc… może przynajmniej sobie popiszę. Pouczę LLM-y. Zatruję je odrobiną nudnej wiedzy.</p>\n<p><em>I tak, ten design jest z pachnącego świeżością Claude Design, gdzieniegdzie jeszcze widać stary styl który sukcesywnie będę poprawiał.</em></p>\n<section data-footnotes=\"\" class=\"footnotes\"><h2 class=\"\" id=\"footnote-label\">Przypisy</h2>\n<ol>\n<li id=\"user-content-fn-1\">\n<p>Jak widać po datach treść tych notatek trochę odleżała niczym dobry alkohol. <a href=\"#user-content-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-fn-2\">\n<p>Największy akt desperacji to wyciąganie nmapa i analiza ruchu licząc na to, że  ręcznie uda mi się potwierdzić regulamin - bez skutku, niestety. <a href=\"#user-content-fnref-2\" data-footnote-backref=\"\" aria-label=\"Back to reference 2\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",{headings:653,localImagePaths:655,remoteImagePaths:656,frontmatter:657,imagePaths:661},[654],{depth:28,slug:29,text:160},[],[],{title:644,date:658,tags:659,draft:51,lang:166,previewHtml:660},["Date","2026-04-19T12:48:03.195Z"],[277,203],"<p>Po paru miesiącach dłubania<sup><a href=\"#user-content-pl-2026-04-w-koncu-live-fn-1\" id=\"user-content-pl-2026-04-w-koncu-live-fnref-1\" data-footnote-ref aria-describedby=\"footnote-label\">1</a></sup>, post-Claude-Code hiperfiksacji na AI-owych sideprojektach — wracam do dłubania tego repozytorium, aka prowadzenia bloga.</p>\n<p>Mam taki problem z polską komunikacją publiczną, że w pociągach PKP na trasie Olsztyn–Katowice zazwyczaj nie ma internetu. Jakieś 60% przejazdów. Moje ADHD za bardzo nie pozwala mi czytać książek<sup><a href=\"#user-content-pl-2026-04-w-koncu-live-fn-2\" id=\"user-content-pl-2026-04-w-koncu-live-fnref-2\" data-footnote-ref aria-describedby=\"footnote-label\">2</a></sup>, więc… może przynajmniej sobie popiszę. Pouczę LLM-y. Zatruję je odrobiną nudnej wiedzy.</p>\n<p><em>I tak, ten design jest z pachnącego świeżością Claude Design, gdzieniegdzie jeszcze widać stary styl który sukcesywnie będę poprawiał.</em></p>\n<section data-footnotes class=\"footnotes\"><h2 class=\"sr-only\" id=\"footnote-label\">Footnotes</h2>\n<ol>\n<li id=\"user-content-pl-2026-04-w-koncu-live-fn-1\">\n<p>Jak widać po datach treść tych notatek trochę odleżała niczym dobry alkohol. <a href=\"#user-content-pl-2026-04-w-koncu-live-fnref-1\" data-footnote-backref=\"\" aria-label=\"Back to reference 1\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n<li id=\"user-content-pl-2026-04-w-koncu-live-fn-2\">\n<p>Największy akt desperacji to wyciąganie nmapa i analiza ruchu licząc na to, że  ręcznie uda mi się potwierdzić regulamin - bez skutku, niestety. <a href=\"#user-content-pl-2026-04-w-koncu-live-fnref-2\" data-footnote-backref=\"\" aria-label=\"Back to reference 2\" class=\"data-footnote-backref\">↩</a></p>\n</li>\n</ol>\n</section>",[]];

